// Inbox = the comments dashboard.
//
// A single comments-only surface (no All / Comments / Other tabs). Every
// row reuses the PR-detail Conversation GhComment card via InboxFeedItem.
// The toolbar is two visually distinct bands: ① "From GitHub" (server
// Search qualifiers, in the URL, re-issue the search) and ② "Refine in
// Pyor" (client-side, over the fetched set). Data + refine logic lives in
// useInboxComments; this screen owns the window chrome, the notifications
// + rate polls (the seen-set cross-references notifications for unread),
// and PR navigation. See the prototype's ShadcnCommentsScreen.

import { useEffect, useMemo, useRef } from 'react';
import { useQuery } from '@tanstack/react-query';
import { CheckCheck, SearchIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { RefreshButton } from '@/components/ui/refresh-button';
import { FetchingBar } from '@/components/ui/fetching-bar';
import { Skeleton } from '@/components/ui/skeleton';
import {
  getNotifications,
  getRateLimit,
  GitHubError,
} from '../github/client';
import type { GHNotification } from '../github/types';
import type { InboxServerFilters } from '../github/inboxComments';
import { PyorWindow } from '../ui/PyorWindow';
import { PRErrorPane } from '../pr/PRErrorPane';
import { EmptyState as SharedEmptyState } from '../ui/EmptyState';
import { presetToSinceISO } from '../ui/DateRangeChip';
import { bridge } from '../desktop/electronBridge';
import { useNavigate, getRouteApi } from '@tanstack/react-router';
import { cleanSearch, type InboxSearch } from '../router/search';
import { openPR, type OpenPRArgs } from '../router/nav';
import { InboxServerBand } from './inbox/InboxServerBand';
import { InboxRefineBand } from './inbox/InboxRefineBand';
import { InboxFeed } from './inbox/InboxFeed';
import { useInboxComments, type RefineState } from './inbox/useInboxComments';
import { useOrgGate } from '../billing/orgGate';
import { GatedListEmptyState } from '../billing/GatedListEmptyState';

const POLL_MS = 60_000;

// Decoupled from the route object (importing it back from router.tsx
// formed an import cycle); the typed API is resolved by route id instead.
const inboxApi = getRouteApi('/inbox');

interface NotificationsScreenProps {
  fluid?: boolean;
  width?: number;
  height?: number;
}

export function NotificationsScreen({
  fluid,
  width = 1320,
  height = 820,
}: NotificationsScreenProps) {
  const navigate = useNavigate();
  const onOpenPR = (args: Omit<OpenPRArgs, 'from'>) =>
    openPR(navigate, { ...args, from: 'inbox' });

  // ── Server band (URL) ────────────────────────────────────────────
  const search = inboxApi.useSearch();
  const patchSearch = (patch: Partial<InboxSearch>) =>
    void navigate({
      to: '/inbox',
      search: cleanSearch({ ...search, ...patch }),
      replace: true,
    });
  const since = useMemo(() => presetToSinceISO(search.date), [search.date]);
  const serverFilters = useMemo<InboxServerFilters>(
    () => ({
      relationship: search.rel,
      scope: search.scope ?? null,
      state: search.state,
      label: search.label ?? null,
      since,
      sort: search.sort,
      commenter: search.commenter ?? null,
      text: search.q ?? null,
    }),
    [search.rel, search.scope, search.state, search.label, since, search.sort, search.commenter, search.q],
  );

  // Refine band (also URL-persisted, but client-side: these filter the
  // fetched set in memory and stay OUT of the query key, so they never
  // refetch). Absent params = unfiltered.
  const refine = useMemo<RefineState>(
    () => ({
      // `type` is defaulted to 'review-inline' by the schema, so it's
      // always present. 'any' must be stored explicitly — dropping it
      // would canonicalise back to the default, not widen the filter.
      type: search.type,
      thread: search.thread ?? 'any',
      unreadOnly: !!search.unread,
      excludeMine: !!search.hidemine,
    }),
    [search.type, search.thread, search.unread, search.hidemine],
  );
  const setRefine = (next: RefineState) =>
    patchSearch({
      type: next.type,
      thread: next.thread === 'any' ? undefined : next.thread,
      unread: next.unreadOnly ? true : undefined,
      hidemine: next.excludeMine ? true : undefined,
    });

  // ── Shared polls (read from cache by useInboxComments) ────────────
  const notifQuery = useQuery({
    queryKey: ['notifications'],
    queryFn: () => getNotifications(),
    refetchInterval: POLL_MS,
    refetchIntervalInBackground: false,
    staleTime: 30_000,
  });
  const rateQuery = useQuery({
    queryKey: ['rate_limit'],
    queryFn: () => getRateLimit(),
    refetchInterval: POLL_MS,
    staleTime: 30_000,
  });
  const rateUsed = rateQuery.data?.resources.core.used ?? null;
  const rateLimit = rateQuery.data?.resources.core.limit ?? 5000;

  const inbox = useInboxComments(serverFilters, refine, onOpenPR);
  const { isOrgAccessible, blockedOrgLogins } = useOrgGate();

  // Native OS banners for fresh comment activity (Electron only). Diff
  // the notifications snapshot each poll; suppressed when focused.
  const rawNotifs = notifQuery.data ?? [];
  const seenIds = useRef<Set<string> | null>(null);
  useEffect(() => {
    const ids = new Set(rawNotifs.map((n) => n.id));
    const b = bridge();
    if (seenIds.current == null || !b || document.hasFocus()) {
      seenIds.current = ids;
      return;
    }
    // Suppress macOS banners for blocked orgs (ADR 0020): a team you can't see
    // in-app shouldn't ping you on the desktop either.
    const fresh = rawNotifs.filter(
      (n) =>
        n.unread &&
        !seenIds.current!.has(n.id) &&
        isOrgAccessible(n.repository.owner.login),
    );
    seenIds.current = ids;
    fresh.forEach((n) =>
      void b.notify({
        title: `${n.repository.owner.login} · ${n.repository.name}`,
        body: n.subject.title,
        threadId: n.id,
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [notifQuery.dataUpdatedAt]);

  const authExpired =
    inbox.authExpired ||
    (notifQuery.error instanceof GitHubError && notifQuery.error.status === 401);
  if (authExpired) {
    return (
      <PRErrorPane
        error={inbox.error ?? notifQuery.error}
        endpoint="/search/issues"
        layout="full"
        onRetry={() => void inbox.refetch()}
      />
    );
  }

  const showFeed = inbox.seenSetReady && !inbox.isPending && inbox.grouped.rows.length > 0;
  const showEmpty =
    inbox.seenSetReady && !inbox.isPending && !inbox.isError && inbox.grouped.rows.length === 0;
  // Background refetch in flight (not the first load — that shows the
  // skeleton). The prior list stays put, so a thin pulsing bar signals
  // it's updating — same affordance as the Pull-requests list.
  const refreshing = inbox.isFetching && !inbox.isPending;

  return (
    <PyorWindow
      width={width}
      height={height}
      fluid={fluid}
      title="Comments"
      subtitle={
        inbox.isPending
          ? 'Loading…'
          : `${inbox.unreadShown} unread · ${inbox.fetched} fetched`
      }
      toolbar={
        <div className="flex items-center gap-2">
          <RefreshButton onRefresh={() => inbox.refetch()} spinning={inbox.isFetching} />
          <Button
            variant="ghost"
            size="sm"
            onClick={() => inbox.markAllRead()}
            disabled={inbox.unreadShown === 0}
          >
            <CheckCheck />
            Mark all read
          </Button>
        </div>
      }
      status={
        <>
          <span>
            {inbox.unreadShown} unread · {inbox.shown} shown
          </span>
          <span className="ml-auto tabular-nums">
            Rate{' '}
            {rateUsed != null
              ? `${rateUsed.toLocaleString()} / ${rateLimit.toLocaleString()}`
              : '— / 5,000'}
          </span>
        </>
      }
    >
      <InboxServerBand
        search={search}
        onPatch={patchSearch}
        query={inbox.query}
        resultCount={inbox.resultCount}
        scopeOptions={inbox.scopeOptions}
        authorOptions={inbox.authorOptions}
      />
      <InboxRefineBand
        refine={refine}
        onRefine={setRefine}
        fetched={inbox.fetched}
        shown={inbox.shown}
      />
      <FetchingBar active={refreshing} />
      {(inbox.isPending || !inbox.seenSetReady) && <FeedSkeleton />}
      {inbox.isError && !inbox.isPending && (
        <div className="p-8 text-center text-[13px] text-pyor-fail">
          Couldn’t load comments: {(inbox.error as Error)?.message}
        </div>
      )}
      {showEmpty &&
        (blockedOrgLogins.size > 0 && !search.q ? (
          // Everything you can see is gated (ADR 0020) — explain it.
          <GatedListEmptyState />
        ) : (
          <SharedEmptyState
            icon={SearchIcon}
            title="No comments match these filters."
            body={
              search.q
                ? `Nothing for “${search.q}” in the fetched set.`
                : 'Loosen the refine filters or widen the GitHub query above.'
            }
          />
        ))}
      {showFeed && (
        <InboxFeed
          grouped={inbox.grouped}
          resultCount={inbox.resultCount}
          pagesLoaded={inbox.pagesLoaded}
          hasNextPage={inbox.hasNextPage}
          isFetchingNextPage={inbox.isFetchingNextPage}
          fetchNextPage={inbox.fetchNextPage}
          isUnread={inbox.isUnread}
          onOpen={inbox.handleOpen}
          onSelect={inbox.handleSelect}
          onMarkRead={inbox.markCommentRead}
          onMarkAll={inbox.markAllRead}
          onReact={inbox.react}
          onDelete={inbox.deleteComment}
          onReply={inbox.replyToComment}
          viewerLogin={inbox.viewerLogin}
        />
      )}
    </PyorWindow>
  );
}

// Six placeholder rows matching the feed item shape.
function FeedSkeleton() {
  return (
    <div className="divide-y">
      {Array.from({ length: 6 }).map((_, i) => (
        <div key={i} className="flex gap-3 px-4 py-3.5">
          <div className="flex-1 space-y-2">
            <div className="flex items-center gap-1.5">
              <Skeleton className="h-3 w-40" />
              <Skeleton className="h-3 w-12" />
              <Skeleton className="ml-auto h-3 w-20" />
            </div>
            <div className="flex items-center gap-2 pt-1">
              <Skeleton className="size-6 rounded-full" />
              <Skeleton className="h-3 w-24" />
            </div>
            <Skeleton className="h-3 w-3/4" />
            {i % 2 === 0 && <Skeleton className="h-16 w-full rounded-md" />}
          </div>
        </div>
      ))}
    </div>
  );
}
