// CommentTypeChip — popover-backed type filter for the Inbox · Comments
// tab. Five entries map to the five InboxComment subtypes; "any"
// drops the filter.
//
// Icons + descriptions mirror the design's COMMENT_TYPE_CFG in
// inbox-comments.jsx.

import {
  CheckCheckIcon,
  ChevronDownIcon,
  Code2Icon,
  FileIcon,
  GitCommitIcon,
  MessageSquareIcon,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import type { InboxCommentType } from '../../github/inboxComments';

export type CommentTypeFilter = 'any' | InboxCommentType;

interface Entry {
  id: CommentTypeFilter;
  label: string;
  desc: string;
  icon: LucideIcon;
}

export const TYPE_ENTRIES: Entry[] = [
  { id: 'any',            label: 'Any type',       desc: 'Show every comment subtype',                  icon: MessageSquareIcon },
  { id: 'conversation',   label: 'PR discussion',  desc: 'Top-level conversation comment',              icon: MessageSquareIcon },
  { id: 'review-inline',  label: 'Inline review',  desc: 'Comment anchored to a specific diff line',    icon: Code2Icon },
  { id: 'review-summary', label: 'Review',         desc: 'Approve / Request changes / Comment wrapper', icon: CheckCheckIcon },
  { id: 'file-level',     label: 'File comment',   desc: 'Comment on a file (no specific line)',        icon: FileIcon },
  { id: 'commit',         label: 'Commit comment', desc: 'Comment anchored to a commit SHA',            icon: GitCommitIcon },
];

function CommentTypeChip({
  value,
  onChange,
}: {
  value: CommentTypeFilter;
  onChange: (v: CommentTypeFilter) => void;
}) {
  const active = value !== 'any';
  const current = TYPE_ENTRIES.find((e) => e.id === value) ?? TYPE_ENTRIES[0];
  const CurrentIcon = current.icon;
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          className={cn(
            'gap-1.5 px-2.5 text-[12px] font-medium',
            active
              ? 'border-primary bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground'
              : 'border-border bg-background text-foreground',
          )}
        >
          <CurrentIcon className="size-3" />
          Type
          <span className={active ? 'text-primary-foreground/70' : 'text-muted-foreground'}>:</span>
          <span>{current.label}</span>
          <ChevronDownIcon className="size-3 opacity-60" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-[280px] p-1">
        <div className="px-2 pb-1 pt-1 text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
          Comment type
        </div>
        {TYPE_ENTRIES.map((e) => {
          const isActive = e.id === value;
          const Icon = e.icon;
          return (
            <button
              key={e.id}
              type="button"
              onClick={() => onChange(e.id)}
              className={cn(
                'flex w-full items-start gap-2 rounded-md px-2 py-1.5 text-left transition-colors',
                isActive ? 'bg-accent' : 'hover:bg-accent/60',
              )}
            >
              <Icon className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
              <div className="min-w-0 flex-1">
                <div className="text-[12px] font-medium text-foreground">{e.label}</div>
                <div className="text-[10.5px] text-muted-foreground">{e.desc}</div>
              </div>
            </button>
          );
        })}
      </PopoverContent>
    </Popover>
  );
}
