// Shared chrome for the two comments-dashboard filter bands.
//
// Visual language mirrors the prototype (comments-inbox.jsx): the
// server "From GitHub" band uses boxy mono "query tokens"; the client
// "Refine in Pyor" band uses soft rounded pills + a real toggle. Colors
// use the app's semantic tokens so both bands are dark-mode-aware (the
// prototype's hard-coded zinc/blue don't survive the theme).

import type { LucideIcon } from 'lucide-react';
import {
  AtSignIcon,
  CheckCircle2Icon,
  ChevronDownIcon,
  ChevronUpIcon,
  CircleDotIcon,
  CircleIcon,
  ClockIcon,
  EyeIcon,
  GitMergeIcon,
  GitPullRequestDraftIcon,
  GitPullRequestIcon,
  MessageSquareIcon,
  SparklesIcon,
  UserIcon,
  XCircleIcon,
} from 'lucide-react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { CommandItem } from '@/components/ui/command';
import { cn } from '@/lib/utils';
import type {
  InboxRelationship,
  InboxSort,
  InboxState,
} from '../../github/inboxComments';

// ── Server-band option config ───────────────────────────────────
export const REL_OPTIONS: {
  q: InboxRelationship;
  label: string;
  icon: LucideIcon;
  desc: string;
}[] = [
  { q: 'involves', label: 'Involves me', icon: CircleDotIcon, desc: 'Author, assignee, commenter or mentioned' },
  { q: 'review-requested', label: 'Review requested', icon: EyeIcon, desc: 'Your review is requested' },
  { q: 'mentions', label: 'Mentions me', icon: AtSignIcon, desc: '@-mentioned in a body or thread' },
  { q: 'commenter', label: 'I commented', icon: MessageSquareIcon, desc: 'Threads you have replied on' },
  { q: 'reviewed-by', label: 'I reviewed', icon: CheckCircle2Icon, desc: 'PRs you submitted a review on' },
  { q: 'assignee', label: 'Assigned to me', icon: UserIcon, desc: 'You are an assignee' },
  { q: 'author', label: 'Authored by me', icon: GitPullRequestIcon, desc: 'Pull requests you opened' },
];

export const STATE_OPTIONS: {
  q: InboxState;
  label: string;
  icon: LucideIcon;
}[] = [
  { q: 'open', label: 'Open', icon: GitPullRequestIcon },
  { q: 'merged', label: 'Merged', icon: GitMergeIcon },
  { q: 'closed', label: 'Closed', icon: XCircleIcon },
  { q: 'draft', label: 'Draft', icon: GitPullRequestDraftIcon },
  { q: 'any', label: 'Any state', icon: CircleIcon },
];

export const SORT_OPTIONS: { q: InboxSort; label: string; icon: LucideIcon }[] = [
  { q: 'updated', label: 'Recently updated', icon: ClockIcon },
  { q: 'created', label: 'Newest', icon: SparklesIcon },
];

// ── Boxy mono query token (server band trigger) ─────────────────
export function ServerToken({
  icon: Icon,
  label,
  value,
  open,
  dimmed,
}: {
  icon?: LucideIcon;
  label?: string;
  value: string;
  open?: boolean;
  dimmed?: boolean;
}) {
  return (
    <span
      className={cn(
        'inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-md border bg-background px-2 text-[12px] transition-colors hover:bg-accent',
        open ? 'border-foreground ring-2 ring-foreground/10' : 'border-border',
      )}
    >
      {Icon && <Icon className="size-3.5 text-muted-foreground" />}
      {label && <span className="text-muted-foreground">{label}</span>}
      <span className={cn('font-medium', dimmed ? 'text-muted-foreground' : 'text-foreground')}>
        {value}
      </span>
      {open ? (
        <ChevronUpIcon className="size-3 text-muted-foreground" />
      ) : (
        <ChevronDownIcon className="size-3 text-muted-foreground" />
      )}
    </span>
  );
}

// ── Soft pill (refine band trigger) ─────────────────────────────
export function RefinePill({
  icon: Icon,
  label,
  value,
  active,
  open,
}: {
  icon?: LucideIcon;
  label: string;
  value?: string | null;
  active?: boolean;
  open?: boolean;
}) {
  const on = active || open;
  return (
    <span
      className={cn(
        'inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-full border px-2.5 text-[12px] font-medium transition-colors',
        on
          ? 'border-primary/40 bg-primary/10 text-primary'
          : 'border-border bg-background text-muted-foreground hover:bg-accent',
      )}
    >
      {Icon && <Icon className={cn('size-3.5', on ? 'text-primary' : 'text-muted-foreground')} />}
      {label}
      {value && (
        <>
          <span className={on ? 'text-primary/40' : 'text-muted-foreground/40'}>·</span>
          <span>{value}</span>
        </>
      )}
      {open ? (
        <ChevronUpIcon className={cn('size-3', on ? 'text-primary/60' : 'text-muted-foreground/60')} />
      ) : (
        <ChevronDownIcon className={cn('size-3', on ? 'text-primary/60' : 'text-muted-foreground/60')} />
      )}
    </span>
  );
}

// ── Real toggle switch (Unread only) ────────────────────────────
export function ToggleSwitch({
  label,
  active,
  onClick,
}: {
  label: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'inline-flex h-7 items-center gap-2 rounded-full border px-2.5 text-[12px] font-medium transition-colors',
        active
          ? 'border-primary/40 bg-primary/10 text-primary'
          : 'border-border bg-background text-muted-foreground hover:bg-accent',
      )}
    >
      <span
        className={cn(
          'relative inline-flex h-3.5 w-6 shrink-0 items-center rounded-full transition-colors',
          active ? 'bg-primary' : 'bg-muted-foreground/40',
        )}
      >
        <span
          className={cn(
            'absolute size-2.5 rounded-full bg-background shadow-sm transition-all',
            active ? 'left-[11px]' : 'left-0.5',
          )}
        />
      </span>
      {label}
    </button>
  );
}

// ── One option row inside a picker ──────────────────────────────
export function MenuRow({
  active,
  icon: Icon,
  dot,
  title,
  desc,
  onSelect,
}: {
  active: boolean;
  icon?: LucideIcon;
  dot?: string;
  title: string;
  desc?: string;
  onSelect: () => void;
}) {
  return (
    <CommandItem onSelect={onSelect} className="gap-2">
      {dot ? (
        <span className={cn('size-2.5 shrink-0 rounded-full', dot)} />
      ) : (
        Icon && <Icon className={cn('size-4 shrink-0', active ? 'text-foreground' : 'text-muted-foreground')} />
      )}
      <span className="flex min-w-0 flex-1 flex-col">
        <span className={cn('truncate text-[12.5px]', active ? 'font-semibold text-foreground' : 'text-foreground/80')}>
          {title}
        </span>
        {desc && <span className="truncate text-[10.5px] text-muted-foreground">{desc}</span>}
      </span>
      {active && <CheckCircle2Icon className="size-3.5 shrink-0 text-foreground" />}
    </CommandItem>
  );
}

// ── Generic picker popover ──────────────────────────────────────
export function PickerPopover({
  open,
  onOpenChange,
  trigger,
  width = 280,
  children,
}: {
  open: boolean;
  onOpenChange: (o: boolean) => void;
  trigger: React.ReactNode;
  width?: number;
  children: React.ReactNode;
}) {
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>{trigger}</PopoverTrigger>
      <PopoverContent align="start" className="p-0" style={{ width }}>
        {children}
      </PopoverContent>
    </Popover>
  );
}
