// InboxFeed — the grouped, virtualized comments feed.
//
// GroupedVirtuoso renders the activity buckets (Today / Yesterday /
// Earlier this week / Older) as sticky headers over the flattened rows,
// each row an InboxFeedItem (PR strip + GhComment). Cursor pagination
// auto-loads on scroll via the shared InfiniteFooter (25/page). J/K
// navigate, e marks the focused row read, ⇧E marks all shown read,
// Enter opens.

import { useEffect, useRef, useState } from 'react';
import { GroupedVirtuoso, type GroupedVirtuosoHandle } from 'react-virtuoso';
import { InfiniteFooter } from '../../ui/InfiniteFooter';
import { InboxFeedItem } from './InboxFeedItem';
import { saveInbox, getInbox } from '../../util/routeStore';
import type { InboxComment } from '../../github/inboxComments';
import type { GHReactions } from '../../github/types';
import type { GroupedComments } from './inboxActivity';

interface Props {
  grouped: GroupedComments;
  resultCount: number;
  pagesLoaded: number;
  hasNextPage: boolean;
  isFetchingNextPage: boolean;
  fetchNextPage: () => void;
  isUnread: (c: InboxComment) => boolean;
  onOpen: (c: InboxComment) => void;
  onSelect: (c: InboxComment) => void;
  onMarkRead: (c: InboxComment) => void;
  onMarkAll: () => void;
  onReact: (subjectId: string, key: keyof GHReactions, add: boolean) => void;
  onDelete: (c: InboxComment) => void;
  onReply: (c: InboxComment, body: string) => Promise<void>;
  viewerLogin?: string;
}

export function InboxFeed({
  grouped,
  resultCount,
  pagesLoaded,
  hasNextPage,
  isFetchingNextPage,
  fetchNextPage,
  isUnread,
  onOpen,
  onSelect,
  onMarkRead,
  onMarkAll,
  onReact,
  onDelete,
  onReply,
  viewerLogin,
}: Props) {
  const rows = grouped.rows;
  const ref = useRef<GroupedVirtuosoHandle | null>(null);
  const [focused, setFocused] = useState(-1);
  const effectiveFocus = focused < 0 || focused >= rows.length ? -1 : focused;

  // Restore prior scroll position once (ref-init so Virtuoso reads it
  // a single time and doesn't fight us on later renders).
  const initialIndexRef = useRef<number | null>(null);
  if (initialIndexRef.current === null) {
    initialIndexRef.current = getInbox().commentsScrollIndex ?? 0;
  }

  // J/K navigation + e/⇧E/Enter, ignored while typing in an input.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      const editable =
        !!t &&
        (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable);
      if (editable) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (e.key === 'j') {
        e.preventDefault();
        setFocused((i) => Math.min(i + 1, rows.length - 1));
      } else if (e.key === 'k') {
        e.preventDefault();
        setFocused((i) => Math.max(i - 1, 0));
      } else if (e.key === 'Enter') {
        const c = rows[effectiveFocus];
        if (c) onOpen(c);
      } else if (e.key === 'E') {
        e.preventDefault();
        onMarkAll();
      } else if (e.key === 'e') {
        const c = rows[effectiveFocus];
        if (c && isUnread(c)) {
          e.preventDefault();
          onMarkRead(c);
        }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [rows, effectiveFocus, isUnread, onOpen, onMarkRead, onMarkAll]);

  useEffect(() => {
    if (effectiveFocus < 0) return;
    ref.current?.scrollIntoView({ index: effectiveFocus, align: 'center' });
  }, [effectiveFocus]);

  return (
    <GroupedVirtuoso
      ref={ref}
      className="flex-1 min-h-0 min-w-0 bg-muted/20"
      groupCounts={grouped.counts}
      initialTopMostItemIndex={initialIndexRef.current}
      rangeChanged={(r) => saveInbox({ commentsScrollIndex: r.startIndex })}
      overscan={600}
      endReached={() => {
        if (hasNextPage && !isFetchingNextPage) fetchNextPage();
      }}
      groupContent={(gi) => (
        <GroupHeader
          label={grouped.buckets[gi]?.label ?? ''}
          count={grouped.counts[gi] ?? 0}
        />
      )}
      itemContent={(index) => {
        const c = rows[index];
        if (!c) return null;
        return (
          <InboxFeedItem
            c={c}
            unread={isUnread(c)}
            onSelect={() => {
              setFocused(index);
              onSelect(c);
            }}
            onReact={onReact}
            onDelete={onDelete}
            onReply={onReply}
            viewerLogin={viewerLogin}
          />
        );
      }}
      components={{
        Footer: () => (
          <InfiniteFooter
            state={
              isFetchingNextPage ? 'loading' : hasNextPage ? 'idle' : 'end'
            }
            shown={rows.length}
            pagesLoaded={pagesLoaded}
            estimatedTotal={resultCount}
            onLoadMore={fetchNextPage}
            caption="Scroll to auto-load · GitHub returns ~25 / page · 1,000 search-result cap"
          />
        ),
      }}
    />
  );
}

function GroupHeader({ label, count }: { label: string; count: number }) {
  return (
    <div className="flex items-center gap-3 border-b bg-background/85 px-4 py-2 backdrop-blur-sm">
      <span className="text-[11px] font-semibold uppercase tracking-wider text-foreground/80">
        {label}
      </span>
      <span className="inline-flex h-[17px] min-w-[17px] items-center justify-center rounded-full bg-muted px-1.5 text-[10px] font-semibold tabular-nums text-muted-foreground">
        {count}
      </span>
      <div className="h-px flex-1 bg-border" />
    </div>
  );
}
