// GraphQL data source for the Inbox · Comments tab.
//
// One round trip per page: `search(query: "is:pr involves:@me
// updated:>SINCE", type: ISSUE)` with `comments`, `reviews`, and
// `reviewThreads { comments { diffHunk } }` nested under each
// PullRequest. ADR 0013 records why this beats the
// notifications-first + REST-backfill hybrid.
//
// The output is a unified `InboxComment[]` — a discriminated union
// across the five GitHub comment surfaces (PR discussion, inline
// review, review summary, file-level, commit). Subtypes share actor,
// author_association, bodyHTML, reactions, timestamps, repo + PR;
// subtype-specific fields (`diffHunk`, file/line/side, `commitSha`,
// review verdict) appear only on their relevant subtype.

import { graphql } from './client';
import type { AuthorAssociation } from './types';

// AuthorAssociation is defined canonically in ./types; re-exported here so
// existing inbox consumers keep importing it from this module.
export type { AuthorAssociation };

export type InboxCommentType =
  | 'conversation'
  | 'review-inline'
  | 'review-summary'
  | 'file-level'
  | 'commit';


export interface ReactionGroup {
  /** GraphQL enum: THUMBS_UP / HEART / HOORAY / LAUGH / etc. */
  content: string;
  count: number;
  viewerHasReacted: boolean;
}

/** The common shape returned for every comment type. */
interface InboxCommentBase {
  id: string;
  /** Numeric REST id (GraphQL `databaseId`). Drives the author-only
   * delete for conversation comments via the REST issue-comments
   * endpoint. Null when GitHub doesn't expose one (e.g. review
   * summaries, which can't be deleted anyway). */
  databaseId: number | null;
  type: InboxCommentType;
  actor: string;
  actorAvatarUrl: string | null;
  /** GitHub `authorAssociation`. BOT inferred from actor "[bot]" suffix. */
  authorAssociation: AuthorAssociation | 'BOT';
  /** Raw Markdown source — rendered via the shared <Markdown> component
   * so code blocks + ```suggestion cards match the PR-detail surface. */
  body: string;
  /** Server-rendered HTML body. Used only for cheap text previews
   * (reply quote) + client-side free-text search. */
  bodyHTML: string;
  /** ISO timestamp. */
  createdAt: string;
  updatedAt: string;
  reactionGroups: ReactionGroup[];
  /** PR coordinates — surfaced in the row's "PR context" line. */
  repo: string;
  owner: string;
  prNumber: number;
  prTitle: string;
  /** URL to open in GitHub (right-most context affordance). */
  htmlUrl: string;
  /** Reply linkage — set on inline-review comments that are not the
   * first comment in their review thread. Drives the "replied to
   * @user" indicator + quoted parent body in the row. Conversation /
   * issue-level comments don't carry this in v1 (the search query
   * returns them flat without parent-id linkage). `body` is the parent's
   * full Markdown source, rendered when the quote is expanded. */
  replyTo: { actor: string; bodyPreview: string; body: string } | null;
}

export interface InboxCommentConversation extends InboxCommentBase {
  type: 'conversation';
}

export interface InboxCommentReviewInline extends InboxCommentBase {
  type: 'review-inline';
  diffHunk: string;
  path: string;
  line: number | null;
  diffSide: 'LEFT' | 'RIGHT' | null;
  isResolved: boolean;
  isOutdated: boolean;
  resolvedBy: string | null;
  /** Numeric REST review-comment id (GraphQL `databaseId`) — drives the
   * precise `acid` deep-link anchor so a row click lands on the exact
   * comment thread in the Changes tab, not just its line. */
  commentId: number | null;
}

export interface InboxCommentReviewSummary extends InboxCommentBase {
  type: 'review-summary';
  reviewState: 'APPROVED' | 'CHANGES_REQUESTED' | 'COMMENTED' | 'DISMISSED' | 'PENDING';
}

export interface InboxCommentFileLevel extends InboxCommentBase {
  type: 'file-level';
  path: string;
}

export interface InboxCommentCommit extends InboxCommentBase {
  type: 'commit';
  commitSha: string;
  path: string | null;
}

export type InboxComment =
  | InboxCommentConversation
  | InboxCommentReviewInline
  | InboxCommentReviewSummary
  | InboxCommentFileLevel
  | InboxCommentCommit;

export interface InboxCommentsPage {
  comments: InboxComment[];
  pageInfo: {
    endCursor: string | null;
    hasNextPage: boolean;
  };
  /** Approximate total (search returns `issueCount` capped at 1000). */
  estimatedTotal: number;
}

// ── GraphQL query ───────────────────────────────────────────────
// Nested: each PR returns the four comment surfaces server-side, so
// one round trip backfills every row's body / diffHunk / reactions.
//
// Per-PR connections are paged at PAGE / INNER_PAGE — chosen so the
// overwhelming majority of PRs come back whole in this single search
// round trip. GitHub orders these subselections oldest-first, so a
// fixed slice would silently drop a big PR's *recent* activity (a new
// thread lands last; a reply lands inside whichever old thread it
// answers). Each connection therefore carries `pageInfo`, and
// `backfillOverflow` drains the remainder per-PR for the rare monster
// PR that exceeds a page. The PR + thread node `id`s exist solely to
// re-enter those connections via `node(id:)` during backfill.
const PAGE = 50;
// Replies per thread are almost always a handful; backfill covers the
// rare long thread, so the first page here stays tight.
const INNER_PAGE = 20;

const COMMENT_FIELDS = /* GraphQL */ `
  id
  databaseId
  body
  bodyHTML
  author { login avatarUrl }
  authorAssociation
  createdAt
  updatedAt
  url
  reactionGroups {
    content
    reactors { totalCount }
    viewerHasReacted
  }
`;

const REVIEW_FIELDS = /* GraphQL */ `
  ${COMMENT_FIELDS}
  state
  submittedAt
`;

const REVIEW_COMMENT_FIELDS = /* GraphQL */ `
  ${COMMENT_FIELDS}
  diffHunk
`;

const REVIEW_THREAD_FIELDS = /* GraphQL */ `
  id
  isResolved
  isOutdated
  resolvedBy { login }
  path
  line
  diffSide
  comments(first: ${INNER_PAGE}) {
    nodes { ${REVIEW_COMMENT_FIELDS} }
    pageInfo { hasNextPage endCursor }
  }
`;

const QUERY = /* GraphQL */ `
  query InboxComments($q: String!, $after: String) {
    search(query: $q, type: ISSUE, first: 25, after: $after) {
      issueCount
      pageInfo { endCursor hasNextPage }
      nodes {
        __typename
        ... on PullRequest {
          id
          number
          title
          url
          repository { nameWithOwner owner { login } name }
          comments(first: ${PAGE}) {
            nodes { ${COMMENT_FIELDS} }
            pageInfo { hasNextPage endCursor }
          }
          reviews(first: ${PAGE}) {
            nodes { ${REVIEW_FIELDS} }
            pageInfo { hasNextPage endCursor }
          }
          reviewThreads(first: ${PAGE}) {
            nodes { ${REVIEW_THREAD_FIELDS} }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
  }
`;

interface RawAuthor { login: string; avatarUrl?: string | null }
interface RawReactionGroup {
  content: string;
  reactors: { totalCount: number };
  viewerHasReacted: boolean;
}
interface RawComment {
  id: string;
  /** Selected for conversation comments (deletable via REST). Absent on
   * review summaries, which carry no deletable databaseId here. */
  databaseId?: number | null;
  body: string;
  bodyHTML: string;
  author: RawAuthor | null;
  authorAssociation: AuthorAssociation;
  createdAt: string;
  updatedAt: string;
  url: string;
  reactionGroups: RawReactionGroup[];
}
interface RawReviewComment extends RawComment {
  diffHunk: string;
  databaseId: number | null;
}
interface RawPageInfo {
  hasNextPage: boolean;
  endCursor: string | null;
}
interface RawConnection<T> {
  nodes: T[];
  pageInfo: RawPageInfo;
}
interface RawReviewThread {
  /** Node id — re-enters this thread's comment connection during backfill. */
  id: string;
  isResolved: boolean;
  isOutdated: boolean;
  resolvedBy: { login: string } | null;
  path: string;
  line: number | null;
  diffSide: 'LEFT' | 'RIGHT' | null;
  comments: RawConnection<RawReviewComment>;
}
interface RawReview extends RawComment {
  state: 'APPROVED' | 'CHANGES_REQUESTED' | 'COMMENTED' | 'DISMISSED' | 'PENDING';
  submittedAt: string | null;
}
interface RawPullRequest {
  __typename: 'PullRequest';
  /** Node id — re-enters this PR's connections during backfill. */
  id: string;
  number: number;
  title: string;
  url: string;
  repository: { nameWithOwner: string; owner: { login: string }; name: string };
  comments: RawConnection<RawComment>;
  reviews: RawConnection<RawReview>;
  reviewThreads: RawConnection<RawReviewThread>;
}
interface RawSearchResult {
  search: {
    issueCount: number;
    pageInfo: { endCursor: string | null; hasNextPage: boolean };
    nodes: (RawPullRequest | { __typename: string })[];
  };
}

// ── Public API ──────────────────────────────────────────────────

/** Relationship qualifier stem (the part before `:@me`). */
export type InboxRelationship =
  | 'involves'
  | 'review-requested'
  | 'mentions'
  | 'commenter'
  | 'reviewed-by'
  | 'assignee'
  | 'author';

/** Pull-request state qualifier. `'any'` omits the `is:` token. */
export type InboxState = 'open' | 'merged' | 'closed' | 'draft' | 'any';

/** Search sort key (always paired with `-desc`). Only the two
 * recency sorts are offered — GitHub's `sort:comments/reactions/
 * interactions` rank the *PR*, not comments, and the feed's activity
 * grouping (by comment updatedAt) overrides them anyway, so they were
 * misleading. */
export type InboxSort = 'updated' | 'created';

/**
 * The server-side ("From GitHub") filter band — everything that
 * composes into the GitHub Search `q=` string and therefore *re-issues*
 * the search. The React Query key is this composed string, so changing
 * any of these refetches while the client refine band (type / thread /
 * unread) never touches the network.
 *
 * Per the comments-dashboard decision (push server-side as far as the
 * Search API allows): comment `author` rides as `commenter:LOGIN` and
 * free `text` rides as `"…" in:comments`. Both narrow the *PR* set
 * server-side; the list keeps a thin client narrowing on top so the
 * feed shows only the matching comments (Search is PR-grain and returns
 * every comment on a matched PR).
 */
export interface InboxServerFilters {
  relationship: InboxRelationship;
  /** Full scope qualifier (`org:foo` / `repo:foo/bar`) or null for all. */
  scope: string | null;
  state: InboxState;
  /** Bare label name (quoted into `label:"…"`) or null. */
  label: string | null;
  /** ISO `since` for `updated:>=YYYY-MM-DD`, or null for any time. */
  since: string | null;
  sort: InboxSort;
  /** Comment author → `commenter:LOGIN`, or null. */
  commenter: string | null;
  /** Free text → `"…" in:comments`, or null. */
  text: string | null;
  /** Blocked-org logins (ADR 0020) → `-org:<login>` so the server excludes them
   * (keeps `issueCount` + pagination correct, not just the rendered rows). */
  excludeOrgs?: string[] | null;
}

export interface FetchInboxCommentsParams extends Partial<InboxServerFilters> {
  cursor?: string | null;
}

export async function fetchInboxComments(
  params: FetchInboxCommentsParams,
): Promise<InboxCommentsPage> {
  const q = buildSearchQuery(params);
  const raw = await graphql<RawSearchResult>(QUERY, {
    q,
    after: params.cursor ?? null,
  });
  const prs = raw.search.nodes.filter(
    (n): n is RawPullRequest => n.__typename === 'PullRequest',
  );
  // Drain the rare PR whose comments overflow a single page. Per-PR and
  // best-effort: a backfill failure degrades to the first page rather
  // than erroring the whole feed.
  await Promise.all(
    prs.filter(needsBackfill).map((pr) =>
      backfillPullRequest(pr).catch((e) => {
        console.warn(`inbox: backfill failed for PR #${pr.number}`, e);
      }),
    ),
  );
  return flattenSearchResult(raw);
}

// ── Overflow backfill ───────────────────────────────────────────
// GitHub orders the nested connections oldest-first, so the first page
// can omit a large PR's most recent comments (a brand-new thread sorts
// last; a fresh reply hides inside an old thread). When any connection
// reports `hasNextPage`, we re-enter it via `node(id:)` and drain the
// remainder into the existing `.nodes` array so `flattenSearchResult`
// sees the whole set. Sequential pagination is inherently unbounded, so
// these drains recurse rather than loop.

function needsBackfill(pr: RawPullRequest): boolean {
  return (
    pr.comments.pageInfo.hasNextPage ||
    pr.reviews.pageInfo.hasNextPage ||
    pr.reviewThreads.pageInfo.hasNextPage ||
    pr.reviewThreads.nodes.some((t) => t.comments.pageInfo.hasNextPage)
  );
}

async function backfillPullRequest(pr: RawPullRequest): Promise<void> {
  await Promise.all([
    drainPrConnection<RawComment>(pr.id, 'comments', COMMENT_FIELDS, pr.comments),
    drainPrConnection<RawReview>(pr.id, 'reviews', REVIEW_FIELDS, pr.reviews),
    drainReviewThreads(pr),
  ]);
}

/** Drain a PR-level `comments` / `reviews` connection into `conn.nodes`. */
async function drainPrConnection<T>(
  prId: string,
  field: 'comments' | 'reviews',
  fields: string,
  conn: RawConnection<T>,
): Promise<void> {
  if (!conn.pageInfo.hasNextPage) return;
  const query = /* GraphQL */ `
    query InboxBackfill($id: ID!, $after: String) {
      node(id: $id) {
        ... on PullRequest {
          ${field}(first: ${PAGE}, after: $after) {
            nodes { ${fields} }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
  `;
  const res = await graphql<{ node: Record<string, RawConnection<T>> | null }>(
    query,
    { id: prId, after: conn.pageInfo.endCursor },
  );
  const next = res.node?.[field];
  if (!next) return;
  conn.nodes.push(...next.nodes);
  conn.pageInfo = next.pageInfo;
  return drainPrConnection(prId, field, fields, conn);
}

/** Drain the thread list, then each thread's overflowing reply set. */
async function drainReviewThreads(pr: RawPullRequest): Promise<void> {
  await drainThreadList(pr.id, pr.reviewThreads);
  // After the list is whole, drain replies for any thread (initial or
  // newly-paged) that itself overflowed INNER_PAGE.
  await Promise.all(
    pr.reviewThreads.nodes
      .filter((t) => t.comments.pageInfo.hasNextPage)
      .map((t) => drainThreadComments(t.id, t.comments)),
  );
}

async function drainThreadList(
  prId: string,
  conn: RawConnection<RawReviewThread>,
): Promise<void> {
  if (!conn.pageInfo.hasNextPage) return;
  const query = /* GraphQL */ `
    query InboxThreadList($id: ID!, $after: String) {
      node(id: $id) {
        ... on PullRequest {
          reviewThreads(first: ${PAGE}, after: $after) {
            nodes { ${REVIEW_THREAD_FIELDS} }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
  `;
  const res = await graphql<{
    node: { reviewThreads: RawConnection<RawReviewThread> } | null;
  }>(query, { id: prId, after: conn.pageInfo.endCursor });
  const next = res.node?.reviewThreads;
  if (!next) return;
  conn.nodes.push(...next.nodes);
  conn.pageInfo = next.pageInfo;
  return drainThreadList(prId, conn);
}

async function drainThreadComments(
  threadId: string,
  conn: RawConnection<RawReviewComment>,
): Promise<void> {
  if (!conn.pageInfo.hasNextPage) return;
  const query = /* GraphQL */ `
    query InboxThreadComments($id: ID!, $after: String) {
      node(id: $id) {
        ... on PullRequestReviewThread {
          comments(first: ${PAGE}, after: $after) {
            nodes { ${REVIEW_COMMENT_FIELDS} }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
  `;
  const res = await graphql<{
    node: { comments: RawConnection<RawReviewComment> } | null;
  }>(query, { id: threadId, after: conn.pageInfo.endCursor });
  const next = res.node?.comments;
  if (!next) return;
  conn.nodes.push(...next.nodes);
  conn.pageInfo = next.pageInfo;
  return drainThreadComments(threadId, conn);
}

/** Prepare a free-text term for the `… in:comments` server qualifier.
 *
 * We send it UNQUOTED with GitHub query-syntax punctuation stripped
 * (`"`, `'`, `:`) → spaces. Rationale: GitHub's quoted-phrase search is
 * unreliable with embedded apostrophes (searching "We don't care"
 * returned nothing), and a stray `:` could be read as a qualifier. The
 * server term is only a coarse recall filter — the list's client
 * narrowing (ciRefine) does the exact, apostrophe-accurate match — so a
 * broad token AND here is the right trade: never drop a real hit. */
function serverTextTerm(text: string): string {
  return text.replace(/["':]/g, ' ').replace(/\s+/g, ' ').trim();
}

/**
 * Compose the live GitHub Search query from the server band. Mirrors
 * the prototype's `ciBuildQuery()` (comments-inbox.jsx). Empty/`any`
 * selections drop their token so the query stays tight.
 */
export function buildSearchQuery(params: FetchInboxCommentsParams): string {
  const relationship = params.relationship ?? 'involves';
  const state = params.state ?? 'open';
  const sort = params.sort ?? 'updated';
  const text = params.text ? serverTextTerm(params.text) : '';
  // GitHub caps the query at 256 chars — cap the negated-org list (client gate
  // is the backstop for any beyond it).
  const excl = (params.excludeOrgs ?? []).slice(0, 15).map((o) => `-org:${o}`);
  return [
    'is:pr',
    `${relationship}:@me`,
    params.scope ?? '',
    state === 'any' ? '' : `is:${state}`,
    'archived:false',
    // The date alone is enough resolution for the date-range presets.
    params.since ? `updated:>=${params.since.slice(0, 10)}` : '',
    params.label ? `label:"${params.label}"` : '',
    params.commenter ? `commenter:${params.commenter}` : '',
    text ? `${text} in:comments` : '',
    ...excl,
    `sort:${sort}-desc`,
  ]
    .filter(Boolean)
    .join(' ');
}

type PRContext = {
  owner: string;
  repo: string;
  prNumber: number;
  prTitle: string;
};

// Top-level PR conversation comments.
function conversationComments(
  pr: RawPullRequest,
  ctx: PRContext,
): InboxComment[] {
  return pr.comments.nodes.map(
    (c) =>
      ({
        ...baseFrom(c, ctx),
        type: 'conversation',
      }) satisfies InboxCommentConversation,
  );
}

// Review summaries — only when the review carries body text (a verdict
// without a body is just a state change; ADR 0013's "review summary subtype").
function reviewSummaries(pr: RawPullRequest, ctx: PRContext): InboxComment[] {
  return pr.reviews.nodes
    .filter((r) => r.bodyHTML)
    .map(
      (r) =>
        ({
          ...baseFrom(r, ctx),
          type: 'review-summary',
          reviewState: r.state,
        }) satisfies InboxCommentReviewSummary,
    );
}

// Inline review-thread comments. Threads are flat and ordered by createdAt,
// so each reply quotes the comment immediately before it (its actual
// predecessor), not the thread head.
function inlineThreadComments(
  pr: RawPullRequest,
  ctx: PRContext,
): InboxComment[] {
  return pr.reviewThreads.nodes.flatMap((thread) =>
    thread.comments.nodes.map((c, i) => {
      const parent = i > 0 ? thread.comments.nodes[i - 1] : null;
      const replyTo = parent
        ? {
            actor: parent.author?.login ?? 'ghost',
            bodyPreview: htmlToPreview(parent.bodyHTML, 120),
            body: parent.body,
          }
        : null;
      return {
        ...baseFrom(c, ctx),
        type: 'review-inline',
        diffHunk: c.diffHunk,
        path: thread.path,
        line: thread.line,
        diffSide: thread.diffSide,
        isResolved: thread.isResolved,
        isOutdated: thread.isOutdated,
        resolvedBy: thread.resolvedBy?.login ?? null,
        commentId: c.databaseId ?? null,
        replyTo,
      } satisfies InboxCommentReviewInline;
    }),
  );
}

function flattenSearchResult(raw: RawSearchResult): InboxCommentsPage {
  const out: InboxComment[] = [];
  raw.search.nodes.forEach((node) => {
    if (node.__typename !== 'PullRequest') return;
    const pr = node as RawPullRequest;
    const ctx: PRContext = {
      owner: pr.repository.owner.login,
      repo: pr.repository.nameWithOwner,
      prNumber: pr.number,
      prTitle: pr.title,
    };
    out.push(
      ...conversationComments(pr, ctx),
      ...reviewSummaries(pr, ctx),
      ...inlineThreadComments(pr, ctx),
    );
  });
  // Sort newest first. Search already returns PRs ordered by updated; the
  // per-PR sub-selections aren't ordered consistently, so resort the
  // flattened list by comment updatedAt for predictable scrolling.
  out.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  return {
    comments: out,
    pageInfo: raw.search.pageInfo,
    estimatedTotal: raw.search.issueCount,
  };
}

function baseFrom(
  c: RawComment,
  ctx: { owner: string; repo: string; prNumber: number; prTitle: string },
): InboxCommentBase {
  const login = c.author?.login ?? 'ghost';
  const isBot = /\[bot\]$/.test(login);
  return {
    id: c.id,
    databaseId: c.databaseId ?? null,
    type: 'conversation', // overwritten by caller
    actor: login,
    actorAvatarUrl: c.author?.avatarUrl ?? null,
    authorAssociation: isBot ? 'BOT' : c.authorAssociation,
    body: c.body,
    bodyHTML: c.bodyHTML,
    createdAt: c.createdAt,
    updatedAt: c.updatedAt,
    reactionGroups: c.reactionGroups.map((g) => ({
      content: g.content,
      count: g.reactors.totalCount,
      viewerHasReacted: g.viewerHasReacted,
    })),
    repo: ctx.repo,
    owner: ctx.owner,
    prNumber: ctx.prNumber,
    prTitle: ctx.prTitle,
    htmlUrl: c.url,
    replyTo: null, // overwritten by caller when applicable
  };
}

/** Strip HTML tags + collapse whitespace, then truncate. Cheap
 * server-rendered HTML → preview converter for the quoted-reply
 * affordance on inline-review replies. */
function htmlToPreview(html: string, max: number): string {
  const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max) : text;
}

// ── Reaction content → emoji map (used by the row footer) ──────
// GitHub returns reactions as enum keys (`THUMBS_UP`, `HEART`, …).
// Mapping kept here so any consumer that wants to render them stays
// off the screen layer.
const REACTION_EMOJI: Record<string, string> = {
  THUMBS_UP: '👍',
  THUMBS_DOWN: '👎',
  LAUGH: '😄',
  HOORAY: '🎉',
  CONFUSED: '😕',
  HEART: '❤️',
  ROCKET: '🚀',
  EYES: '👀',
};
