import { Link } from '@tanstack/react-router';
import {
  AlertTriangleIcon,
  CheckCircleIcon,
  Code2Icon,
  CornerDownRightIcon,
  FileIcon,
  GitCommitIcon,
  GitPullRequestIcon,
  MessageSquareIcon,
  XCircleIcon,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Collapse, CollapseChevron } from '@/components/ui/collapse';
import { cn } from '@/lib/utils';
import { GhComment } from '../../pr/conversation/GhComment';
import { GhComposer } from '../../pr/conversation/GhComposer';
import { useGithubAssetsUploader } from '../../pr/conversation/composer/useGithubAssetsUploader';
import { Markdown } from '@/ui/Markdown';
import type { GHReactions } from '../../github/types';
import type { GHReactor } from '../../github/client';
import { AssocBadge } from './AssocBadge';
import { InboxCommentSnippet } from './InboxCommentSnippet';
import {
  type InboxComment,
  type InboxCommentType,
} from '../../github/inboxComments';
import {
  canDeleteInboxComment,
  canReplyToInboxComment,
  inboxCommentOpenArgs,
} from './useInboxComments';
import { prLinkProps } from '../../router/nav';

const TYPE_CFG: Record<
  InboxCommentType,
  { label: string; icon: LucideIcon; variant: 'default' | 'secondary' | 'outline' }
> = {
  conversation: { label: 'PR discussion', icon: MessageSquareIcon, variant: 'secondary' },
  'review-inline': { label: 'Inline review', icon: Code2Icon, variant: 'default' },
  'review-summary': { label: 'Review', icon: CheckCircleIcon, variant: 'default' },
  'file-level': { label: 'File comment', icon: FileIcon, variant: 'outline' },
  commit: { label: 'Commit comment', icon: GitCommitIcon, variant: 'outline' },
};

// GraphQL reaction enum → the eight GHReactions count keys (for
// GhComment's read-only reactions strip).
type ReactionCountKey =
  | '+1' | '-1' | 'laugh' | 'hooray' | 'confused' | 'heart' | 'rocket' | 'eyes';
const REACTION_KEY: Record<string, ReactionCountKey> = {
  THUMBS_UP: '+1',
  THUMBS_DOWN: '-1',
  LAUGH: 'laugh',
  HOORAY: 'hooray',
  CONFUSED: 'confused',
  HEART: 'heart',
  ROCKET: 'rocket',
  EYES: 'eyes',
};

function toReactions(c: InboxComment): GHReactions | undefined {
  const counts: Record<ReactionCountKey, number> = {
    '+1': 0, '-1': 0, laugh: 0, hooray: 0, confused: 0, heart: 0, rocket: 0, eyes: 0,
  };
  let total = 0;
  c.reactionGroups.forEach((g) => {
    const key = REACTION_KEY[g.content];
    if (key && g.count > 0) {
      counts[key] = g.count;
      total += g.count;
    }
  });
  if (total === 0) return undefined;
  return { url: '', total_count: total, ...counts };
}

// Synthesize the reactor list GhReactions uses to decide "did I react?".
// We don't fetch the full list (no extra round trip) — we already know
// the viewer's own reactions from each group's `viewerHasReacted`, which
// is all the toggle needs (add vs remove). Others stay as counts.
function viewerReactors(c: InboxComment, viewerLogin?: string): GHReactor[] {
  if (!viewerLogin) return [];
  return c.reactionGroups
    .filter((g) => g.viewerHasReacted)
    .map((g) => ({
      id: 0,
      content: REACTION_KEY[g.content] ?? g.content,
      user: { login: viewerLogin, avatar_url: '' },
      created_at: '',
    }));
}

interface ChipProps {
  icon: LucideIcon;
  label: string;
  tone: string;
}

function Chip({ icon: Icon, label, tone }: ChipProps) {
  return (
    <span className={cn('inline-flex h-[18px] items-center gap-1 rounded-full border px-1.5 text-[10px] font-semibold', tone)}>
      <Icon className="size-2.5" />
      {label}
    </span>
  );
}

function stateChipOf(c: InboxComment): ChipProps | null {
  if (c.type !== 'review-inline') return null;
  if (c.isOutdated)
    return { icon: AlertTriangleIcon, label: 'Outdated', tone: 'text-amber-700 border-amber-200 bg-amber-50 dark:text-amber-300 dark:border-amber-900 dark:bg-amber-950/40' };
  if (c.isResolved)
    return { icon: CheckCircleIcon, label: 'Resolved', tone: 'text-emerald-700 border-emerald-200 bg-emerald-50 dark:text-emerald-300 dark:border-emerald-900 dark:bg-emerald-950/40' };
  return { icon: MessageSquareIcon, label: 'Unresolved', tone: 'text-muted-foreground border-border bg-background' };
}

function verdictChipOf(c: InboxComment): ChipProps | null {
  if (c.type !== 'review-summary') return null;
  switch (c.reviewState) {
    case 'APPROVED':
      return { icon: CheckCircleIcon, label: 'Approved', tone: 'text-emerald-700 border-emerald-200 bg-emerald-50 dark:text-emerald-300 dark:border-emerald-900 dark:bg-emerald-950/40' };
    case 'CHANGES_REQUESTED':
      return { icon: XCircleIcon, label: 'Changes requested', tone: 'text-red-700 border-red-200 bg-red-50 dark:text-red-300 dark:border-red-900 dark:bg-red-950/40' };
    case 'COMMENTED':
      return { icon: MessageSquareIcon, label: 'Commented', tone: 'text-muted-foreground border-border bg-muted' };
    default:
      return null;
  }
}

function ContextStrip({
  c,
  unread,
  linkProps,
  onSelect,
}: {
  c: InboxComment;
  unread: boolean;
  linkProps: ReturnType<typeof prLinkProps>;
  onSelect: () => void;
}) {
  const typeCfg = TYPE_CFG[c.type];
  const TypeIcon = typeCfg.icon;
  const stateChip = stateChipOf(c);
  const verdictChip = verdictChipOf(c);
  return (
    <div className="flex flex-wrap items-center gap-x-2 gap-y-1 pl-0.5">
      {unread && <span className="size-1.5 shrink-0 rounded-full bg-primary" title="Unread" />}
      <GitPullRequestIcon className="size-3.5 shrink-0 text-muted-foreground" />
      <Link
        {...linkProps}
        onClick={onSelect}
        title={
          c.type === 'review-inline'
            ? 'Open the diff at this comment'
            : 'Open this pull request'
        }
        className={cn(
          'truncate text-left text-[12.5px] hover:underline',
          unread ? 'font-semibold text-foreground' : 'font-medium text-foreground/90',
        )}
        style={{ maxWidth: 440 }}
      >
        {c.prTitle}
      </Link>
      <span className="shrink-0 font-mono text-[11px] text-muted-foreground/70">#{c.prNumber}</span>
      <span className="text-muted-foreground/40">·</span>
      <span className="shrink-0 text-[11.5px] text-muted-foreground">{c.repo}</span>
      {c.type === 'review-inline' && (
        <>
          <span className="text-muted-foreground/40">·</span>
          <Link
            {...linkProps}
            onClick={onSelect}
            title="Open the diff at this comment"
            className="inline-flex min-w-0 items-center gap-1 font-mono text-[11px] text-muted-foreground hover:text-foreground hover:underline"
          >
            <FileIcon className="size-3 shrink-0" />
            <span className="min-w-0 truncate">{c.path}</span>
            {c.line != null && <span className="text-muted-foreground/70">:{c.line}</span>}
          </Link>
        </>
      )}
      {c.type === 'file-level' && (
        <>
          <span className="text-muted-foreground/40">·</span>
          <Link
            {...linkProps}
            onClick={onSelect}
            title="Open this file in the diff"
            className="inline-flex min-w-0 items-center gap-1 font-mono text-[11px] text-muted-foreground hover:text-foreground hover:underline"
          >
            <FileIcon className="size-3 shrink-0" />
            <span className="min-w-0 truncate">{c.path}</span>
          </Link>
        </>
      )}
      {c.type === 'commit' && (
        <>
          <span className="text-muted-foreground/40">·</span>
          <span className="inline-flex shrink-0 items-center gap-1 font-mono text-[11px] text-muted-foreground">
            <GitCommitIcon className="size-3" />
            {c.commitSha.slice(0, 7)}
          </span>
        </>
      )}
      <div className="ml-auto flex shrink-0 flex-wrap items-center gap-1.5">
        {verdictChip && <Chip {...verdictChip} />}
        {stateChip && <Chip {...stateChip} />}
        <Badge variant={typeCfg.variant} className="gap-1 px-1.5 py-0 text-[10px]">
          <TypeIcon className="size-2.5" />
          {typeCfg.label}
        </Badge>
        <AssocBadge role={c.authorAssociation} />
      </div>
    </div>
  );
}

// Render the comment body through the SAME <Markdown> component the
// PR-detail Conversation tab uses — so code blocks and ```suggestion
// cards look identical across surfaces. The gh-body--inbox wrapper keeps
// the inbox image-size cap. (The reply quote above shows the immediate
// predecessor; the diff an inline comment is anchored to rides in
// GhComment's diffSlice, not here.)
function CommentBody({ c }: { c: InboxComment }) {
  return (
    <div className="space-y-2">
      {c.replyTo && <QuotedParent replyTo={c.replyTo} />}
      <div className="gh-body--inbox">
        <Markdown source={c.body} size="sm" />
      </div>
    </div>
  );
}

// The comment this reply is answering — collapsed to a one-line preview,
// expandable to the full parent rendered as Markdown.
function QuotedParent({
  replyTo,
}: {
  replyTo: NonNullable<InboxComment['replyTo']>;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="overflow-hidden rounded-md border-l-2 border-muted-foreground/40 bg-muted/60 text-[11.5px]">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center gap-1 px-2.5 py-1 text-left text-muted-foreground hover:text-foreground"
        title={open ? 'Hide the quoted comment' : 'Show the quoted comment'}
      >
        <CornerDownRightIcon className="size-3 shrink-0 text-muted-foreground/70" />
        <span className="shrink-0 not-italic text-muted-foreground/70">
          @{replyTo.actor}:
        </span>
        {!open && (
          <span className="min-w-0 flex-1 truncate italic">
            “{replyTo.bodyPreview}…”
          </span>
        )}
        <CollapseChevron open={open} className="ml-auto size-3" />
      </button>
      <Collapse open={open}>
        <div className="gh-body--inbox border-t border-muted-foreground/20 px-2.5 py-1.5">
          <Markdown source={replyTo.body} size="sm" />
        </div>
      </Collapse>
    </div>
  );
}

interface Props {
  c: InboxComment;
  unread: boolean;
  onSelect: () => void;
  onReact: (subjectId: string, key: keyof GHReactions, add: boolean) => void;
  onDelete: (c: InboxComment) => void;
  onReply: (c: InboxComment, body: string) => Promise<void>;
  viewerLogin?: string;
}

export function InboxFeedItem({
  c,
  unread,
  onSelect,
  onReact,
  onDelete,
  onReply,
  viewerLogin,
}: Props) {
  const canDelete = canDeleteInboxComment(c, viewerLogin);
  const canReply = canReplyToInboxComment(c);
  const [replying, setReplying] = useState(false);
  const uploadImage = useGithubAssetsUploader();
  const repoName = c.repo.split('/')[1] ?? c.repo;
  const linkProps = prLinkProps({ ...inboxCommentOpenArgs(c), from: 'inbox' });
  const diffSlice =
    c.type === 'review-inline' && c.diffHunk ? (
      <InboxCommentSnippet
        diffHunk={c.diffHunk}
        path={c.path}
        line={c.line}
        diffSide={c.diffSide}
        linkProps={linkProps}
        onSelect={onSelect}
      />
    ) : undefined;
  return (
    <article
      className={cn(
        'relative border-b bg-background px-4 py-3.5',
        unread ? 'bg-primary/[0.04]' : 'hover:bg-muted/30',
      )}
    >
      {unread && <span className="absolute inset-y-0 left-0 w-[3px] bg-primary/80" />}
      <div className="mb-2">
        <ContextStrip c={c} unread={unread} linkProps={linkProps} onSelect={onSelect} />
      </div>
      <GhComment
        author={c.actor}
        authorAvatarUrl={c.actorAvatarUrl ?? undefined}
        age={formatRelative(c.updatedAt || c.createdAt)}
        diffSlice={diffSlice}
        reactions={toReactions(c)}
        onAddReaction={(key) => onReact(c.id, key, true)}
        onRemoveReaction={(key) => onReact(c.id, key, false)}
        listReactors={() => Promise.resolve(viewerReactors(c, viewerLogin))}
        viewerLogin={viewerLogin}
        canEdit={canDelete}
        onDelete={canDelete ? () => onDelete(c) : undefined}
        onReply={canReply ? () => setReplying(true) : undefined}
        highlight={c.type === 'review-inline' && c.isResolved ? 'resolved' : null}
        htmlUrl={c.htmlUrl}
        copyContext={
          c.type === 'review-inline'
            ? { file: c.path, line: c.line, code: '' }
            : undefined
        }
      >
        <CommentBody c={c} />
      </GhComment>
      {replying && (
        <div className="mt-2">
          <GhComposer
            variant="inline"
            compact
            draftKey={`inbox:${c.id}:reply`}
            placeholder="Reply… (Markdown · ⌘⏎ to send)"
            submitLabel="Reply"
            autoFocus
            minHeight={84}
            onUploadImage={uploadImage}
            mentionContext={{ owner: c.owner, repo: repoName, number: c.prNumber }}
            onCancel={() => setReplying(false)}
            onSubmit={async (body) => {
              await onReply(c, body);
              setReplying(false);
            }}
          />
        </div>
      )}
    </article>
  );
}

function formatRelative(iso: string): string {
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 60_000) return 'just now';
  const mins = Math.round(ms / 60_000);
  if (mins < 60) return `${mins}m`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  const days = Math.round(hrs / 24);
  if (days < 30) return `${days}d`;
  return `${Math.round(days / 30)}mo`;
}
