// Activity bucketing for the comments feed.
//
// Groups rows into Today / Yesterday / Earlier this week / Older by
// their `updatedAt`, with sticky group headers. Mirrors the prototype's
// CI_BUCKETS / ciBucketOf (comments-inbox.jsx) but keys off a real ISO
// timestamp instead of the fixture's "2h" age string.

import type { InboxComment } from '../../github/inboxComments';

export type ActivityBucketId = 'today' | 'yesterday' | 'week' | 'older';

export interface ActivityBucket {
  id: ActivityBucketId;
  label: string;
}

const ACTIVITY_BUCKETS: ActivityBucket[] = [
  { id: 'today', label: 'Today' },
  { id: 'yesterday', label: 'Yesterday' },
  { id: 'week', label: 'Earlier this week' },
  { id: 'older', label: 'Older' },
];

/** Local midnight N days before today, in ms. */
function midnightDaysAgo(days: number): number {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate() - days).getTime();
}

/** Which activity bucket an ISO timestamp falls into. */
function bucketOf(iso: string): ActivityBucketId {
  const t = new Date(iso).getTime();
  if (t >= midnightDaysAgo(0)) return 'today';
  if (t >= midnightDaysAgo(1)) return 'yesterday';
  if (t >= midnightDaysAgo(7)) return 'week';
  return 'older';
}

export interface GroupedComments {
  /** Buckets that have at least one row, in display order. */
  buckets: ActivityBucket[];
  /** Per-bucket row counts, index-aligned with `buckets`. */
  counts: number[];
  /** Rows flattened in bucket order (what GroupedVirtuoso renders). */
  rows: InboxComment[];
}

/**
 * Partition filtered comments into activity buckets, preserving the
 * incoming (updated-desc) order within each. Empty buckets are dropped
 * so GroupedVirtuoso never renders a header with zero rows.
 */
export function groupByActivity(comments: InboxComment[]): GroupedComments {
  const byId = new Map<ActivityBucketId, InboxComment[]>();
  comments.forEach((c) => {
    const id = bucketOf(c.updatedAt || c.createdAt);
    const list = byId.get(id);
    if (list) list.push(c);
    else byId.set(id, [c]);
  });
  const buckets = ACTIVITY_BUCKETS.filter((b) => byId.has(b.id));
  const counts = buckets.map((b) => byId.get(b.id)!.length);
  const rows = buckets.flatMap((b) => byId.get(b.id)!);
  return { buckets, counts, rows };
}
