// Dexie-backed seen-set for InboxComment unread reconstruction.
//
// Per ADR 0015: GraphQL search returns comments without unread bits.
// We reconstruct `unread` by combining two signals — `/notifications`
// cross-reference + this local seen-set. A comment is "seen" once
// the user has either:
//   (a) clicked the row,
//   (b) hit Mark-read on the row, or
//   (c) hit Mark-all-read on the Comments tab.
//
// Storage is keyed by GraphQL node-id; ~25 bytes per entry. ~10k
// comments/year ≈ 250 KB, well inside IndexedDB budgets. Pruned by
// `updatedAt < now - 90d` on app boot.

import Dexie, { type Table } from 'dexie';

interface SeenComment {
  id: string;
  /** Comment updatedAt at the time we marked it seen. Used to prune
   * entries older than 90 days. */
  updatedAt: string;
  /** When the user marked it seen. */
  seenAt: number;
}

class SeenDB extends Dexie {
  seen!: Table<SeenComment, string>;
  constructor() {
    super('pyor-inbox-comments');
    this.version(1).stores({ seen: 'id, updatedAt' });
  }
}

const db = new SeenDB();

/** Returns the set of comment IDs the viewer has already seen.
 * Materialized once on mount; mutations push through `markSeen`. */
export async function loadSeenSet(): Promise<Set<string>> {
  const rows = await db.seen.toArray();
  return new Set(rows.map((r) => r.id));
}

export async function markSeen(id: string, updatedAt: string): Promise<void> {
  await db.seen.put({ id, updatedAt, seenAt: Date.now() });
}

export async function markManySeen(
  entries: { id: string; updatedAt: string }[],
): Promise<void> {
  if (entries.length === 0) return;
  const now = Date.now();
  await db.seen.bulkPut(
    entries.map((e) => ({ id: e.id, updatedAt: e.updatedAt, seenAt: now })),
  );
}

/** Prune entries older than 90 days. Call on app boot. */
async function pruneStaleSeen(): Promise<number> {
  const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60_000).toISOString();
  return await db.seen.where('updatedAt').below(cutoff).delete();
}
