// InboxServerBand — the "From GitHub" filter band.
//
// Server-side, authoritative GitHub Search qualifiers composed into a
// live `q=` string. Every control re-issues the search (these fields
// live in the /inbox URL). Rendered as boxy mono query tokens, per the
// prototype's CIServerBand (comments-inbox.jsx). Author (→ commenter:)
// and free text (→ in:comments) live here too, by project decision.

import { useRef, useState } from 'react';
import { FolderIcon, SearchIcon, TagIcon, UserIcon, UsersIcon } from 'lucide-react';
import { GithubMark } from '../../ui/GithubMark';
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandList,
} from '@/components/ui/command';
import { Separator } from '@/components/ui/separator';
import type { InboxSearch } from '../../router/search';
import { DateRangeChip } from '../../ui/DateRangeChip';
import {
  MenuRow,
  PickerPopover,
  REL_OPTIONS,
  STATE_OPTIONS,
  SORT_OPTIONS,
  ServerToken,
} from './inboxBandUI';
import type { ScopeOption } from './useInboxComments';

type PatchFn = (patch: Partial<InboxSearch>) => void;
type Pop = 'rel' | 'scope' | 'state' | 'label' | 'sort' | 'author' | null;

interface Props {
  search: InboxSearch;
  onPatch: PatchFn;
  query: string;
  resultCount: number;
  scopeOptions: ScopeOption[];
  authorOptions: string[];
}

export function InboxServerBand({
  search,
  onPatch,
  query,
  resultCount,
  scopeOptions,
  authorOptions,
}: Props) {
  const [pop, setPop] = useState<Pop>(null);
  const toggle = (p: Pop) => (o: boolean) => setPop(o ? p : null);

  const rel = REL_OPTIONS.find((o) => o.q === search.rel) ?? REL_OPTIONS[0];
  const state = STATE_OPTIONS.find((o) => o.q === search.state) ?? STATE_OPTIONS[0];
  const sort = SORT_OPTIONS.find((o) => o.q === search.sort) ?? SORT_OPTIONS[0];
  const scope = scopeOptions.find((o) => o.q === search.scope) ?? null;

  return (
    <div className="flex flex-wrap items-center gap-2 border-b bg-muted/40 px-4 py-2.5">
      <span className="flex size-[22px] shrink-0 items-center justify-center rounded-md bg-foreground text-background" title="From GitHub (server filters)">
        <GithubMark className="size-3.5" />
      </span>
      <Separator orientation="vertical" className="h-7" />

      {/* Relationship */}
      <PickerPopover
        open={pop === 'rel'}
        onOpenChange={toggle('rel')}
        width={320}
        trigger={<span><ServerToken icon={rel.icon} value={rel.label} open={pop === 'rel'} /></span>}
      >
        <Command>
          <CommandList>
            <CommandGroup heading="Your relationship to the PR">
              {REL_OPTIONS.map((o) => (
                <MenuRow
                  key={o.q}
                  active={o.q === search.rel}
                  icon={o.icon}
                  title={o.label}
                  desc={o.desc}
                  onSelect={() => {
                    onPatch({ rel: o.q });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* Scope */}
      <PickerPopover
        open={pop === 'scope'}
        onOpenChange={toggle('scope')}
        width={300}
        trigger={
          <span>
            <ServerToken icon={FolderIcon} label="in" value={scope ? scope.label : 'all repos'} open={pop === 'scope'} dimmed={!scope} />
          </span>
        }
      >
        <Command>
          <CommandInput placeholder="Filter repositories…" />
          <CommandList>
            <CommandGroup heading="Scope">
              <MenuRow
                active={!search.scope}
                icon={FolderIcon}
                title="All repositories"
                desc="everything you can read"
                onSelect={() => {
                  onPatch({ scope: undefined });
                  setPop(null);
                }}
              />
              {scopeOptions.map((o) => (
                <MenuRow
                  key={o.q}
                  active={o.q === search.scope}
                  icon={o.kind === 'org' ? UsersIcon : FolderIcon}
                  title={o.label}
                  onSelect={() => {
                    onPatch({ scope: o.q });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* State */}
      <PickerPopover
        open={pop === 'state'}
        onOpenChange={toggle('state')}
        width={220}
        trigger={<span><ServerToken icon={state.icon} value={state.q === 'any' ? 'any' : state.q} open={pop === 'state'} dimmed={state.q === 'any'} /></span>}
      >
        <Command>
          <CommandList>
            <CommandGroup heading="Pull-request state">
              {STATE_OPTIONS.map((o) => (
                <MenuRow
                  key={o.q}
                  active={o.q === search.state}
                  icon={o.icon}
                  title={o.label}
                  onSelect={() => {
                    onPatch({ state: o.q });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* Label */}
      <LabelToken
        value={search.label ?? null}
        open={pop === 'label'}
        onOpenChange={toggle('label')}
        onApply={(v) => {
          onPatch({ label: v || undefined });
          setPop(null);
        }}
      />

      {/* Updated within — the full-featured chip from the old Comments
          tab (presets + mini-calendar + live `since:` readout). */}
      <DateRangeChip
        value={search.date}
        onChange={(d) => onPatch({ date: d })}
      />

      <Separator orientation="vertical" className="h-7" />

      {/* Sort */}
      <PickerPopover
        open={pop === 'sort'}
        onOpenChange={toggle('sort')}
        width={230}
        trigger={<span><ServerToken label="sort" value={`${sort.q}↓`} open={pop === 'sort'} /></span>}
      >
        <Command>
          <CommandList>
            <CommandGroup heading="Order results (desc)">
              {SORT_OPTIONS.map((o) => (
                <MenuRow
                  key={o.q}
                  active={o.q === search.sort}
                  icon={o.icon}
                  title={o.label}
                  onSelect={() => {
                    onPatch({ sort: o.q });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* Author → commenter: */}
      <PickerPopover
        open={pop === 'author'}
        onOpenChange={toggle('author')}
        width={240}
        trigger={<span><ServerToken icon={UsersIcon} label="by" value={search.commenter ?? 'anyone'} open={pop === 'author'} dimmed={!search.commenter} /></span>}
      >
        <Command>
          <CommandInput placeholder="Filter commenters…" />
          <CommandList>
            <CommandGroup heading="Comment author (commenter:)">
              <MenuRow
                active={!search.commenter}
                icon={UsersIcon}
                title="Anyone"
                onSelect={() => {
                  onPatch({ commenter: undefined });
                  setPop(null);
                }}
              />
              {authorOptions.map((a) => (
                <MenuRow
                  key={a}
                  active={a === search.commenter}
                  icon={UserIcon}
                  title={a}
                  onSelect={() => {
                    onPatch({ commenter: a });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* Free text → in:comments */}
      <SearchToken value={search.q ?? ''} onChange={(v) => onPatch({ q: v || undefined })} />

      <div className="ml-auto flex items-center gap-2.5">
        <code className="hidden max-w-[360px] truncate rounded-md border bg-background px-2.5 py-1 font-mono text-[10.5px] text-muted-foreground 2xl:inline">
          <span className="text-muted-foreground/60">q=</span>
          {query}
        </code>
        <span className="inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-50 px-2 py-1 text-[11px] font-medium text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">
          <span className="size-1.5 rounded-full bg-emerald-500" />
          {resultCount.toLocaleString()} PRs
        </span>
      </div>
    </div>
  );
}

// ── Label token (typed; same Command-list look as the others) ────
function LabelToken({
  value,
  open,
  onOpenChange,
  onApply,
}: {
  value: string | null;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  onApply: (v: string) => void;
}) {
  const [draft, setDraft] = useState(value ?? '');
  const term = draft.trim();
  return (
    <PickerPopover
      open={open}
      onOpenChange={(o) => {
        if (o) setDraft(value ?? '');
        onOpenChange(o);
      }}
      width={250}
      trigger={<span><ServerToken icon={TagIcon} label="label" value={value || 'any'} open={open} dimmed={!value} /></span>}
    >
      {/* shouldFilter=false — the typed text BECOMES the label to apply,
          it doesn't filter a fixed list. The "Apply" row is first so
          Enter applies the typed value rather than clearing. */}
      <Command shouldFilter={false}>
        <CommandInput value={draft} onValueChange={setDraft} placeholder="Type a label…" />
        <CommandList>
          <CommandGroup heading="Filter by label">
            {term && term !== value && (
              <MenuRow
                active={false}
                icon={TagIcon}
                title={`Apply “${term}”`}
                onSelect={() => onApply(term)}
              />
            )}
            <MenuRow
              active={!value}
              icon={TagIcon}
              title="Any label"
              onSelect={() => onApply('')}
            />
          </CommandGroup>
        </CommandList>
      </Command>
    </PickerPopover>
  );
}

// ── Free-text search (debounced → in:comments) ──────────────────
function SearchToken({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) {
  // Local state so typing is instant; a ref-debounce pushes to the URL
  // (and the network) ~400ms after the user pauses. Seeded once from the
  // URL value — external resets are rare on this surface.
  const [text, setText] = useState(value);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const push = (v: string) => {
    setText(v);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => onChange(v.trim()), 400);
  };
  return (
    <div className="relative flex h-7 w-60 items-center gap-1.5 rounded-md border bg-background px-2">
      <SearchIcon className="size-3 text-muted-foreground" />
      <input
        value={text}
        onChange={(e) => push(e.target.value)}
        placeholder="Search comments (in:comments)…"
        className="min-w-0 flex-1 border-none bg-transparent text-[12px] text-foreground outline-none placeholder:text-muted-foreground"
      />
    </div>
  );
}
