// useInboxComments — the comments-dashboard data + refine engine.
//
// Owns: the cursor-paginated GraphQL search (keyed ONLY on the composed
// server `q=` string, so client refine never refetches), the unread
// reconstruction (notifications cross-ref + Dexie seen-set, ADR 0015),
// the client refine pass (comment type · thread state · unread-only),
// the thin client narrowing that keeps the feed comment-accurate for the
// server `commenter:` / `in:comments` qualifiers, activity grouping, and
// the mark-read / open actions.
//
// Server vs client split lives in github/inboxComments.ts. Everything in
// the "From GitHub" band is in `filters` (→ the query key); everything
// here in `refine` runs in memory over what was already fetched.

import { useCallback, useMemo } from 'react';
import {
  keepPreviousData,
  useInfiniteQuery,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  buildSearchQuery,
  fetchInboxComments,
  type InboxComment,
  type InboxCommentsPage,
  type InboxServerFilters,
  type ReactionGroup,
} from '../../github/inboxComments';
import {
  createIssueComment,
  deleteIssueComment,
  deleteReviewComment,
  GitHubError,
  markNotificationRead,
  replyToReviewComment,
  setReactionByNodeId,
  type GqlReactionContent,
} from '../../github/client';
import type { GHNotification, GHReactions } from '../../github/types';
import type { InfiniteData } from '@tanstack/react-query';
import type { OpenPRArgs } from '../../router/nav';
import {
  loadSeenSet,
  markManySeen,
  markSeen,
} from './seenStore';
import type { CommentTypeFilter } from './CommentTypeChip';
import { groupByActivity, type GroupedComments } from './inboxActivity';
import { useOrgGate } from '../../billing/orgGate';
import { useConfirm } from '@/components/confirm';
import { track, Events, repoProps } from '../../observability';

export type ThreadFilter = 'any' | 'resolved' | 'unresolved';

/** Client-only refine band — never hits the network. */
export interface RefineState {
  type: CommentTypeFilter;
  thread: ThreadFilter;
  unreadOnly: boolean;
  /** Drop the viewer's own comments so the feed is others' only. Kept
   * client-side on purpose: a server `-commenter:@me` would prune whole
   * PRs the viewer commented on (Search is PR-grain), hiding others'
   * replies on the very threads they're involved in. */
  excludeMine: boolean;
}

// Inbox defaults to the inline-review surface (it's a code-review tool);
// keep this in sync with the `type` default in inboxSearchSchema.
export const REFINE_DEFAULTS: RefineState = {
  type: 'review-inline',
  thread: 'any',
  unreadOnly: false,
  excludeMine: false,
};

// OpenPRArgs is defined canonically in router/nav (imported above); re-exported
// so this hook's onOpenPR callback signature shares the one definition.
export type { OpenPRArgs };

interface ScopeOption {
  /** Full qualifier — `org:foo` or `repo:foo/bar`. */
  q: string;
  label: string;
  kind: 'org' | 'repo';
}

/** Lowercase + fold smart quotes/apostrophes to ASCII so substring
 * search tolerates typographic punctuation in rendered bodies. */
function normalizeText(s: string): string {
  return s
    .toLowerCase()
    .replace(/[‘’ʼ]/g, "'")
    .replace(/[“”]/g, '"');
}

/** GHReactions summary key → GraphQL ReactionContent enum. */
const KEY_TO_GQL: Partial<Record<keyof GHReactions, GqlReactionContent>> = {
  '+1': 'THUMBS_UP',
  '-1': 'THUMBS_DOWN',
  laugh: 'LAUGH',
  hooray: 'HOORAY',
  confused: 'CONFUSED',
  heart: 'HEART',
  rocket: 'ROCKET',
  eyes: 'EYES',
};

/** Optimistically bump a comment's reactionGroups for the viewer's
 * add/remove (groups are keyed by the GraphQL `content` enum). */
function bumpGroups(
  groups: ReactionGroup[],
  content: GqlReactionContent,
  add: boolean,
): ReactionGroup[] {
  const idx = groups.findIndex((g) => g.content === content);
  if (add) {
    if (idx < 0) return [...groups, { content, count: 1, viewerHasReacted: true }];
    if (groups[idx].viewerHasReacted) return groups;
    const next = [...groups];
    next[idx] = { ...next[idx], count: next[idx].count + 1, viewerHasReacted: true };
    return next;
  }
  if (idx < 0 || !groups[idx].viewerHasReacted) return groups;
  const count = groups[idx].count - 1;
  const next = [...groups];
  if (count <= 0) next.splice(idx, 1);
  else next[idx] = { ...next[idx], count, viewerHasReacted: false };
  return next;
}

/** Whether the viewer can delete this comment from the dashboard.
 * Only the author's own comments, and only the types GitHub lets us
 * delete by id: conversation (issue) comments via REST `databaseId`,
 * and inline review comments via their `commentId`. Review summaries
 * are submitted reviews — GitHub has no delete API for them. */
export function canDeleteInboxComment(
  c: InboxComment,
  viewerLogin?: string,
): boolean {
  if (!viewerLogin || c.actor !== viewerLogin) return false;
  if (c.type === 'conversation') return c.databaseId != null;
  if (c.type === 'review-inline') return c.commentId != null;
  return false;
}

/** Whether the dashboard can post a reply to this comment. Inline review
 * comments thread via the REST replies endpoint (needs the head/thread
 * `commentId`); top-level PR discussion replies go up as a new issue
 * comment. The other surfaces (review summaries, file-level, commit) have
 * no reply target GitHub lets us write to from here. */
export function canReplyToInboxComment(c: InboxComment): boolean {
  if (c.type === 'review-inline') return c.commentId != null;
  if (c.type === 'conversation') return true;
  return false;
}

export function inboxCommentOpenArgs(c: InboxComment): Omit<OpenPRArgs, 'from'> {
  const anchor =
    c.type === 'review-inline'
      ? {
          path: c.path,
          line: c.line,
          diffSide: c.diffSide,
          commentId: c.commentId ?? undefined,
        }
      : c.type === 'file-level'
        ? { path: c.path }
        : undefined;
  return {
    owner: c.owner,
    repo: c.repo.split('/')[1] ?? c.repo,
    number: c.prNumber,
    tab:
      c.type === 'review-inline' || c.type === 'file-level'
        ? 'changes'
        : 'description',
    anchor,
  };
}

export function useInboxComments(
  filters: InboxServerFilters,
  refine: RefineState,
  onOpenPR: (args: OpenPRArgs) => void,
) {
  const queryClient = useQueryClient();
  const confirm = useConfirm();
  const { isOrgAccessible, blockedOrgLogins } = useOrgGate();
  // Sorted, stable list of blocked-org logins → server-side `-org:` exclusion
  // (keeps issueCount + pagination correct, not just the rendered rows).
  const excludeOrgs = useMemo(
    () => [...blockedOrgLogins].sort(),
    [blockedOrgLogins],
  );

  // The composed GitHub query IS the cache key (sharing #1): client
  // refine stays out of it, so refining is free and re-applying a server
  // filter returns the cached page instantly.
  const q = useMemo(
    () => buildSearchQuery({ ...filters, excludeOrgs }),
    [filters, excludeOrgs],
  );

  const infinite = useInfiniteQuery({
    queryKey: ['inbox-comments', q] as const,
    queryFn: ({ pageParam }) =>
      fetchInboxComments({
        ...filters,
        excludeOrgs,
        cursor: pageParam as string | null,
      }),
    getNextPageParam: (last) =>
      last.pageInfo.hasNextPage ? last.pageInfo.endCursor : undefined,
    initialPageParam: null as string | null,
    // Freshness: refetch when the user returns to the inbox (mount) or
    // refocuses the window, throttled by a 30s staleTime so bouncing
    // around doesn't re-issue the search. keepPreviousData keeps the old
    // list on screen while the background refetch runs (no flicker), so
    // a reaction/comment made elsewhere (incl. the PR-detail page or
    // GitHub web) shows up on return without a manual Refresh.
    staleTime: 30_000,
    refetchOnMount: true,
    refetchOnWindowFocus: true,
    placeholderData: keepPreviousData,
  });

  const authExpired =
    infinite.error instanceof GitHubError && infinite.error.status === 401;

  // Seen-set lives in the TanStack cache (sharing #2 / ADR 0015) so it
  // survives unmount and updates optimistically via setQueryData.
  const seenSetQuery = useQuery({
    queryKey: ['inbox-seen-set'],
    queryFn: loadSeenSet,
    staleTime: Infinity,
  });
  const seenSet = seenSetQuery.data ?? new Set<string>();
  const seenSetReady = seenSetQuery.isSuccess;

  // Notifications are read straight from the shared cache (sharing #2) —
  // the screen's poll populates ['notifications']; no extra round trip.
  const notifications =
    queryClient.getQueryData<GHNotification[]>(['notifications']) ?? [];

  // Viewer login from the shared cache (AppSidebar fetches ['viewer']),
  // used to resolve "did *I* react?" for the reaction toggle.
  const viewerLogin = queryClient.getQueryData<{ login: string }>([
    'viewer',
  ])?.login;

  // Blocked orgs (ADR 0020) drop out of the comments dashboard here — which
  // cascades to the feed, the scope picker, and the author list below.
  const allComments: InboxComment[] = useMemo(
    () =>
      (infinite.data?.pages.flatMap((p) => p.comments) ?? []).filter((c) =>
        isOrgAccessible(c.owner),
      ),
    [infinite.data, isOrgAccessible],
  );
  const resultCount = infinite.data?.pages[0]?.estimatedTotal ?? 0;

  const isUnread = useCallback(
    (c: InboxComment): boolean => {
      const matchByUrl = notifications.find(
        (n) => n.subject.latest_comment_url === c.htmlUrl,
      );
      if (matchByUrl) return matchByUrl.unread;
      const sameRepoPR = notifications.find(
        (n) =>
          n.repository.full_name === c.repo &&
          n.subject.url?.includes(`/${c.prNumber}`),
      );
      if (sameRepoPR?.unread) return true;
      return !seenSet.has(c.id);
    },
    [notifications, seenSet],
  );

  // Scope picker options, derived from the fetched set (data-driven, like
  // the prototype). Orgs first, then repos, each as a full qualifier.
  const scopeOptions = useMemo<ScopeOption[]>(() => {
    const orgs = new Map<string, number>();
    const repos = new Map<string, number>();
    allComments.forEach((c) => {
      orgs.set(c.owner, (orgs.get(c.owner) ?? 0) + 1);
      repos.set(c.repo, (repos.get(c.repo) ?? 0) + 1);
    });
    const orgOpts: ScopeOption[] = Array.from(orgs.keys())
      .sort()
      .map((o) => ({ q: `org:${o}`, label: o, kind: 'org' }));
    const repoOpts: ScopeOption[] = Array.from(repos.keys())
      .sort()
      .map((r) => ({ q: `repo:${r}`, label: r, kind: 'repo' }));
    return [...orgOpts, ...repoOpts];
  }, [allComments]);

  // Comment-author (→ commenter:) options, from the fetched set.
  const authorOptions = useMemo<string[]>(
    () => Array.from(new Set(allComments.map((c) => c.actor))).sort(),
    [allComments],
  );

  // Client refine + the thin narrowing that keeps the feed accurate for
  // the server `commenter:` / `in:comments` qualifiers (Search is
  // PR-grain, so a matched PR still carries every author's comments).
  const filtered = useMemo(() => {
    let out = allComments;
    if (refine.type !== 'any') out = out.filter((c) => c.type === refine.type);
    if (refine.thread === 'resolved')
      out = out.filter((c) => c.type === 'review-inline' && c.isResolved);
    if (refine.thread === 'unresolved')
      out = out.filter((c) => c.type === 'review-inline' && !c.isResolved);
    if (refine.unreadOnly) out = out.filter(isUnread);
    // Hide the viewer's own comments (others-only view). Comment grain,
    // so it keeps others' replies on PRs the viewer also commented on.
    if (refine.excludeMine && viewerLogin)
      out = out.filter((c) => c.actor !== viewerLogin);
    // Mirror the server `updated:>=` date qualifier at comment grain.
    // Search matches by *PR* updatedAt, so a recently-touched PR drags
    // along comments older than the range — drop those here. Date-grain
    // (YYYY-MM-DD) to match the server's `updated:>=` comparison.
    if (filters.since) {
      const sinceDay = filters.since.slice(0, 10);
      out = out.filter((c) => c.updatedAt.slice(0, 10) >= sinceDay);
    }
    // Mirror the server author qualifier at comment grain.
    if (filters.commenter)
      out = out.filter((c) => c.actor === filters.commenter);
    // Mirror the server free-text qualifier at comment grain. Normalize
    // smart quotes/apostrophes so a curly-quoted body still matches a
    // straight-quoted query (and vice versa) — GitHub renders some
    // bodies with typographic punctuation.
    const text = filters.text ? normalizeText(filters.text) : '';
    if (text) {
      out = out.filter((c) => {
        const hay = normalizeText(
          `${c.actor} ${c.prTitle} ${c.repo} ${'path' in c ? (c.path ?? '') : ''}`,
        );
        if (hay.includes(text)) return true;
        return normalizeText(c.bodyHTML.replace(/<[^>]+>/g, ' ')).includes(text);
      });
    }
    return out;
  }, [allComments, refine, isUnread, viewerLogin, filters.since, filters.commenter, filters.text]);

  const grouped: GroupedComments = useMemo(
    () => groupByActivity(filtered),
    [filtered],
  );
  const unreadShown = useMemo(
    () => filtered.filter(isUnread).length,
    [filtered, isUnread],
  );

  // ── Mark-read ────────────────────────────────────────────────────
  const markSeenLocal = useCallback(
    (entries: { id: string; updatedAt: string }[]): void => {
      if (entries.length === 0) return;
      void (entries.length === 1
        ? markSeen(entries[0].id, entries[0].updatedAt)
        : markManySeen(entries));
      queryClient.setQueryData<Set<string>>(['inbox-seen-set'], (prev) => {
        const next = new Set(prev ?? []);
        entries.forEach((e) => next.add(e.id));
        return next;
      });
    },
    [queryClient],
  );

  const markCommentRead = useCallback(
    (c: InboxComment): void => {
      markSeenLocal([{ id: c.id, updatedAt: c.updatedAt }]);
      const matchByUrl = notifications.find(
        (n) => n.subject.latest_comment_url === c.htmlUrl,
      );
      if (!matchByUrl) return;
      void markNotificationRead(matchByUrl.id).catch(() => {
        toast.error('Could not mark notification read');
      });
      queryClient.setQueryData<GHNotification[]>(['notifications'], (curr) =>
        curr?.map((n) => (n.id === matchByUrl.id ? { ...n, unread: false } : n)),
      );
    },
    [markSeenLocal, notifications, queryClient],
  );

  // Add / remove the viewer's reaction on a comment (by GraphQL node id,
  // which works across every comment surface). Optimistically bump the
  // inbox-comments cache, then fire the mutation; roll back on failure.
  const react = useCallback(
    (subjectId: string, key: keyof GHReactions, add: boolean): void => {
      const content = KEY_TO_GQL[key];
      if (!content) return;
      const queryKey = ['inbox-comments', q] as const;
      const prev =
        queryClient.getQueryData<InfiniteData<InboxCommentsPage>>(queryKey);
      queryClient.setQueryData<InfiniteData<InboxCommentsPage>>(
        queryKey,
        (data) =>
          data
            ? {
                ...data,
                pages: data.pages.map((p) => ({
                  ...p,
                  comments: p.comments.map((c) =>
                    c.id === subjectId
                      ? ({
                          ...c,
                          reactionGroups: bumpGroups(c.reactionGroups, content, add),
                        } as InboxComment)
                      : c,
                  ),
                })),
              }
            : data,
      );
      void setReactionByNodeId(subjectId, content, add).catch(() => {
        if (prev) queryClient.setQueryData(queryKey, prev);
        toast.error(add ? 'Could not add reaction' : 'Could not remove reaction');
      });
    },
    [q, queryClient],
  );

  // Delete the viewer's own comment (conversation or inline review).
  // Confirm, optimistically drop it from every cached page, then fire
  // the type-appropriate REST delete; roll back + toast on failure.
  const deleteComment = useCallback(
    async (c: InboxComment): Promise<void> => {
      if (!canDeleteInboxComment(c, viewerLogin)) return;
      const ok = await confirm({
        title: 'Delete comment?',
        description: "Delete this comment? This can't be undone.",
        confirmLabel: 'Delete',
        tone: 'destructive',
      });
      if (!ok) return;
      const owner = c.owner;
      const repo = c.repo.split('/')[1] ?? c.repo;
      const queryKey = ['inbox-comments', q] as const;
      const prev =
        queryClient.getQueryData<InfiniteData<InboxCommentsPage>>(queryKey);
      queryClient.setQueryData<InfiniteData<InboxCommentsPage>>(
        queryKey,
        (data) =>
          data
            ? {
                ...data,
                pages: data.pages.map((p) => ({
                  ...p,
                  comments: p.comments.filter((x) => x.id !== c.id),
                })),
              }
            : data,
      );
      try {
        await (c.type === 'review-inline'
          ? deleteReviewComment(owner, repo, c.commentId!)
          : deleteIssueComment(owner, repo, c.databaseId!));
        markSeenLocal([{ id: c.id, updatedAt: c.updatedAt }]);
        toast.success('Comment deleted');
      } catch (e) {
        if (prev) queryClient.setQueryData(queryKey, prev);
        toast.error('Could not delete comment', {
          description:
            e instanceof GitHubError
              ? `${e.status}: ${e.message}`
              : e instanceof Error
                ? e.message
                : String(e),
        });
      }
    },
    [q, queryClient, viewerLogin, markSeenLocal, confirm],
  );

  // Post a reply to a comment from the dashboard. Inline review comments
  // append to their thread via the REST replies endpoint (keyed on the
  // thread's `commentId`, which inherits path/line/side); PR-discussion
  // comments go up as a new issue comment. On success we mark the source
  // read and invalidate the feed so the freshly-posted reply surfaces.
  // Errors toast here and re-throw so GhComposer keeps the draft + stays
  // open (its onSubmit contract: "throws bubble up — caller toasts").
  const replyToComment = useCallback(
    async (c: InboxComment, body: string): Promise<void> => {
      const repo = c.repo.split('/')[1] ?? c.repo;
      try {
        if (c.type === 'review-inline' && c.commentId != null)
          await replyToReviewComment(c.owner, repo, c.prNumber, c.commentId, body);
        else if (c.type === 'conversation')
          await createIssueComment(c.owner, repo, c.prNumber, body);
        else throw new Error('Reply is not supported for this comment type');
      } catch (e) {
        toast.error('Could not post reply', {
          description:
            e instanceof GitHubError
              ? `${e.status}: ${e.message}`
              : e instanceof Error
                ? e.message
                : String(e),
        });
        throw e;
      }
      markSeenLocal([{ id: c.id, updatedAt: c.updatedAt }]);
      toast.success('Reply posted');
      void queryClient.invalidateQueries({ queryKey: ['inbox-comments', q] });
    },
    [q, queryClient, markSeenLocal],
  );

  const markAllRead = useCallback((): void => {
    const unread = filtered.filter(isUnread);
    if (unread.length === 0) return;
    markSeenLocal(unread.map((c) => ({ id: c.id, updatedAt: c.updatedAt })));
    toast.success(`Marked ${unread.length} comments read`);
  }, [filtered, isUnread, markSeenLocal]);

  const handleSelect = useCallback(
    (c: InboxComment): void => {
      markCommentRead(c);
      track(Events.NotificationClicked, {
        comment_type: c.type,
        ...repoProps({
          owner: c.owner,
          repo: c.repo.split('/')[1] ?? c.repo,
          prNumber: c.prNumber,
        }),
      });
    },
    [markCommentRead],
  );

  const handleOpen = useCallback(
    (c: InboxComment): void => {
      handleSelect(c);
      onOpenPR(inboxCommentOpenArgs(c));
    },
    [handleSelect, onOpenPR],
  );

  return {
    // query state
    isPending: infinite.isPending,
    isError: infinite.isError,
    error: infinite.error,
    authExpired,
    refetch: infinite.refetch,
    isFetching: infinite.isFetching,
    hasNextPage: !!infinite.hasNextPage,
    isFetchingNextPage: infinite.isFetchingNextPage,
    fetchNextPage: infinite.fetchNextPage,
    pagesLoaded: infinite.data?.pages.length ?? 0,
    // data
    query: q,
    resultCount,
    fetched: allComments.length,
    shown: filtered.length,
    unreadShown,
    grouped,
    scopeOptions,
    authorOptions,
    seenSetReady,
    isUnread,
    viewerLogin,
    // actions
    markCommentRead,
    markAllRead,
    handleSelect,
    handleOpen,
    react,
    deleteComment,
    replyToComment,
  };
}

type InboxCommentsModel = ReturnType<typeof useInboxComments>;
export type { ScopeOption };
