// InboxCommentSnippet — compact diff_hunk renderer for an inline
// review row.
//
// GitHub's `diff_hunk` is a unified-diff fragment: one `@@ -a,b +c,d @@`
// header line followed by ~4-6 context/added/deleted lines. For the
// triage surface we render it as a tinted monospace block — added
// rows tinted green, deleted rows tinted red, the anchored line
// outlined in amber. Tokens come through @pierre/diffs's shared
// highlighter (same one the Files-tab CodeView uses), so the colors
// + theme backdrop match whatever the user has set in DiffPreferences.
//
// "View in diff" links through to the PR detail Files tab with the
// path + line anchor — same nav contract as a row click.

import { useMemo } from 'react';
import { Link } from '@tanstack/react-router';
import { Code2Icon, ExternalLinkIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { prLinkProps } from '../../router/nav';
import { useDiffSnippetHighlight } from '../../pr/conversation/useDiffSnippetHighlight';
import {
  buildChangeRangeMap,
  splitTokensByRanges,
  type CharRange,
  type OverlayRow,
} from '../../pr/conversation/lineDiffOverlay';
import { usePrefs } from '../../util/usePrefs';

interface SnippetProps {
  diffHunk: string;
  path: string;
  line: number | null;
  diffSide: 'LEFT' | 'RIGHT' | null;
  linkProps?: ReturnType<typeof prLinkProps>;
  onSelect?: () => void;
}

interface ParsedLine {
  kind: 'context' | 'add' | 'del' | 'header';
  ln: number | null;
  text: string;
}

function parseDiffHunk(hunk: string, anchorLine: number | null): ParsedLine[] {
  const out: ParsedLine[] = [];
  const lines = hunk.split('\n');
  // The header looks like `@@ -10,5 +12,7 @@`. The first number after
  // the `+` tells us the starting line on the new file side — and
  // since `anchorLine` is also on the new side for `RIGHT` comments,
  // we walk forward from there. For `LEFT` (deleted) anchors we use
  // the old-side start instead.
  let newLn = 0;
  let oldLn = 0;
  for (const ln of lines) {
    if (ln.startsWith('@@')) {
      const m = ln.match(/@@ -(\d+),?\d* \+(\d+),?\d* @@/);
      if (m) {
        oldLn = parseInt(m[1], 10);
        newLn = parseInt(m[2], 10);
      }
      out.push({ kind: 'header', ln: null, text: ln });
      continue;
    }
    if (ln.startsWith('+')) {
      out.push({ kind: 'add', ln: newLn, text: ln.slice(1) });
      newLn++;
    } else if (ln.startsWith('-')) {
      out.push({ kind: 'del', ln: oldLn, text: ln.slice(1) });
      oldLn++;
    } else {
      out.push({ kind: 'context', ln: newLn, text: ln.startsWith(' ') ? ln.slice(1) : ln });
      newLn++;
      oldLn++;
    }
  }
  // Drop the leading header — design omits it.
  return out.filter((p) => p.kind !== 'header');
}

export function InboxCommentSnippet({ diffHunk, path, line, diffSide, linkProps, onSelect }: SnippetProps) {
  const parsed = parseDiffHunk(diffHunk, line);
  // GitHub's diff_hunk fragments can be quite long. The design caps
  // at the last 4-6 lines (where the anchor sits) — slice from the
  // end so the anchored line is in the visible window.
  const visible = parsed.slice(-6);
  const lang = inferLang(path);

  // Tokenise the visible rows through the lib's shared highlighter so
  // the snippet matches the Files-tab CodeView's coloring + theme
  // backdrop. The joined text is stable as long as the underlying
  // diff_hunk doesn't change — memoise so the hook doesn't re-fire
  // on every parent render (e.g. the row's unread tick).
  const joinedText = useMemo(
    () => visible.map((p) => p.text).join('\n'),
    [visible],
  );
  const { lines: tokenLines, themeFg, themeBg } = useDiffSnippetHighlight(
    joinedText,
    path,
  );

  // Char-level diff overlay on paired -/+ rows, matching the Files-tab
  // CodeView and the conversation DiffHunkSnippet. Keyed off the same
  // lineDiffStyle pref so all three surfaces emphasise the same chars.
  const { prefs } = usePrefs();
  const changeRanges = useMemo<Map<number, CharRange[]>>(() => {
    const overlayRows: OverlayRow[] = visible.map((p) => ({
      kind: p.kind === 'add' ? 'add' : p.kind === 'del' ? 'del' : 'other',
      text: p.text,
    }));
    return buildChangeRangeMap(overlayRows, prefs.lineDiffStyle);
  }, [visible, prefs.lineDiffStyle]);

  return (
    // max-w-full + min-w-0 keep the snippet from pushing the row wider
    // than its column — long file paths and long lines now scroll
    // horizontally inside the snippet instead of overflowing the article.
    <div className="max-w-full min-w-0 overflow-hidden rounded-md border bg-muted/40">
      <div className="flex items-center gap-2 border-b bg-background px-2.5 py-1 text-[11px] text-muted-foreground">
        <Code2Icon className="size-3 shrink-0 text-muted-foreground/70" />
        <span className="min-w-0 truncate font-mono text-foreground">{path}</span>
        {lang && (
          <span className="shrink-0 rounded-sm bg-muted px-1 py-0 text-[9.5px] font-medium uppercase tracking-wide text-muted-foreground">
            {lang}
          </span>
        )}
        {line != null && (
          <span className="shrink-0 font-mono text-[10.5px] text-muted-foreground">
            :{line}
            {diffSide === 'LEFT' && (
              <span className="ml-1 rounded bg-red-50 px-1 text-[9.5px] font-medium text-red-700">
                −
              </span>
            )}
          </span>
        )}
        {linkProps && (
          <Link
            {...linkProps}
            onClick={onSelect}
            className="ml-auto shrink-0 inline-flex items-center gap-1 rounded text-muted-foreground hover:text-foreground"
          >
            <ExternalLinkIcon className="size-3" />
            View in diff
          </Link>
        )}
      </div>
      <div
        className="px-0 py-1 font-mono text-[11px] leading-[16px]"
        style={{
          backgroundColor: themeBg ?? undefined,
          color: themeFg ?? undefined,
        }}
      >
        {visible.map((p, i) => {
          const isAnchor =
            line != null &&
            p.ln === line &&
            ((diffSide === 'LEFT' && p.kind === 'del') ||
              (diffSide !== 'LEFT' && p.kind !== 'del'));
          // +/- tints layer ON TOP of the theme bg via /10 alpha so
          // the Shiki backdrop still bleeds through. Without alpha
          // the row tints would obliterate the theme colour and the
          // snippet would look bisected.
          const rowBg =
            p.kind === 'add'
              ? 'bg-pyor-pass/10'
              : p.kind === 'del'
                ? 'bg-pyor-fail/10'
                : isAnchor
                  ? 'bg-pyor-warn/10'
                  : '';
          const marker =
            p.kind === 'add' ? (
              <span className="text-pyor-pass">+</span>
            ) : p.kind === 'del' ? (
              <span className="text-pyor-fail">−</span>
            ) : (
              <span className="text-transparent">·</span>
            );
          const tokenLine = tokenLines?.[i];
          const ranges = changeRanges.get(i);
          const segments =
            tokenLine &&
            tokenLine.tokens.length > 0 &&
            ranges &&
            ranges.length > 0
              ? splitTokensByRanges(tokenLine.tokens, ranges)
              : null;
          const emphasisClass =
            p.kind === 'del'
              ? 'rounded-[2px] bg-pyor-fail/30'
              : p.kind === 'add'
                ? 'rounded-[2px] bg-pyor-pass/30'
                : '';
          return (
            <div key={i} className={cn('flex', rowBg)}>
              <span className="w-9 shrink-0 select-none pr-2 text-right tabular-nums text-muted-foreground/70">
                {p.ln ?? ''}
              </span>
              <span className="w-3 shrink-0 select-none text-center">{marker}</span>
              <code className="min-w-0 flex-1 whitespace-pre-wrap break-words pr-4">
                {segments ? (
                  segments.map((seg, j) => (
                    <span
                      key={j}
                      className={seg.changed ? emphasisClass : undefined}
                      style={seg.color ? { color: seg.color } : undefined}
                    >
                      {seg.text}
                    </span>
                  ))
                ) : tokenLine && tokenLine.tokens.length > 0 ? (
                  tokenLine.tokens.map((tok, j) => (
                    <span
                      key={j}
                      style={tok.color ? { color: tok.color } : undefined}
                    >
                      {tok.content}
                    </span>
                  ))
                ) : (
                  p.text
                )}
              </code>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function inferLang(path: string): string | null {
  const m = path.match(/\.([a-zA-Z0-9]+)$/);
  if (!m) return null;
  const ext = m[1].toLowerCase();
  const map: Record<string, string> = {
    ts: 'ts',
    tsx: 'tsx',
    js: 'js',
    jsx: 'jsx',
    py: 'py',
    go: 'go',
    rs: 'rs',
    rb: 'rb',
    java: 'java',
    kt: 'kt',
    swift: 'swift',
    sh: 'sh',
    yaml: 'yaml',
    yml: 'yaml',
    json: 'json',
    md: 'md',
    css: 'css',
    html: 'html',
  };
  return map[ext] ?? ext;
}
