// AssocBadge — author_association chip in the comments-feed PR context
// strip (InboxFeedItem).
//
// Tones lifted from the design's ASSOC_CFG (inbox-comments.jsx).
// Suppressed for the boring default `NONE` since most commenters are
// just contributors and the visual noise isn't worth the signal.

import type { AuthorAssociation } from '../../github/inboxComments';
import { cn } from '@/lib/utils';

type Assoc = AuthorAssociation | 'BOT';

const TONES: Partial<Record<Assoc, { label: string; tone: string }>> = {
  OWNER: {
    label: 'OWNER',
    tone: 'text-amber-700 border-amber-200 bg-amber-50',
  },
  MEMBER: {
    label: 'MEMBER',
    tone: 'text-zinc-700 border-zinc-200 bg-zinc-50',
  },
  COLLABORATOR: {
    label: 'COLLABORATOR',
    tone: 'text-zinc-700 border-zinc-200 bg-zinc-50',
  },
  CONTRIBUTOR: {
    label: 'CONTRIBUTOR',
    tone: 'text-zinc-500 border-zinc-200 bg-background',
  },
  FIRST_TIME_CONTRIBUTOR: {
    label: '1ST-TIME',
    tone: 'text-emerald-700 border-emerald-200 bg-emerald-50',
  },
  FIRST_TIMER: {
    label: '1ST-TIME',
    tone: 'text-emerald-700 border-emerald-200 bg-emerald-50',
  },
  BOT: {
    label: 'BOT',
    tone: 'text-blue-700 border-blue-200 bg-blue-50',
  },
};

export function AssocBadge({ role }: { role: Assoc }) {
  const cfg = TONES[role];
  if (!cfg) return null;
  return (
    <span
      className={cn(
        'inline-flex h-[15px] items-center rounded-full border px-1.5 text-[9.5px] font-semibold uppercase tracking-wider',
        cfg.tone,
      )}
    >
      {cfg.label}
    </span>
  );
}
