// InboxRefineBand — the "Refine in Pyor" filter band.
//
// Client-side only. These run in memory over the already-fetched set —
// the things GitHub Search genuinely can't do at comment granularity:
// comment type (the five surfaces), thread resolution (GraphQL
// isResolved), and the local unread set. Rendered as soft pills + a real
// toggle, with the "N fetched → M shown" ledger. Mirrors the prototype's
// CIRefineBand (comments-inbox.jsx).

import { useState } from 'react';
import {
  CheckCircle2Icon,
  CircleDotIcon,
  FilterIcon,
  MessageSquareIcon,
  RotateCcwIcon,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import {
  Command,
  CommandGroup,
  CommandList,
} from '@/components/ui/command';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { TYPE_ENTRIES } from './CommentTypeChip';
import {
  MenuRow,
  PickerPopover,
  RefinePill,
  ToggleSwitch,
} from './inboxBandUI';
import {
  REFINE_DEFAULTS,
  type RefineState,
  type ThreadFilter,
} from './useInboxComments';

const THREAD_OPTIONS: {
  q: ThreadFilter;
  label: string;
  icon: LucideIcon;
  desc: string;
}[] = [
  { q: 'any', label: 'Any thread', icon: MessageSquareIcon, desc: 'Resolved and open' },
  { q: 'unresolved', label: 'Unresolved', icon: CircleDotIcon, desc: 'Still needs a reply or fix' },
  { q: 'resolved', label: 'Resolved', icon: CheckCircle2Icon, desc: 'Marked done on the thread' },
];

interface Props {
  refine: RefineState;
  onRefine: (next: RefineState) => void;
  fetched: number;
  shown: number;
}

export function InboxRefineBand({ refine, onRefine, fetched, shown }: Props) {
  const [pop, setPop] = useState<'type' | 'thread' | null>(null);
  const toggle = (p: 'type' | 'thread') => (o: boolean) => setPop(o ? p : null);

  const typeCfg = TYPE_ENTRIES.find((e) => e.id === refine.type) ?? TYPE_ENTRIES[0];
  const thread = THREAD_OPTIONS.find((t) => t.q === refine.thread) ?? THREAD_OPTIONS[0];
  // "Reset" shows only when refine deviates from the screen defaults
  // (type defaults to inline review, not "any").
  const dirty =
    refine.type !== REFINE_DEFAULTS.type ||
    refine.thread !== REFINE_DEFAULTS.thread ||
    refine.unreadOnly !== REFINE_DEFAULTS.unreadOnly ||
    refine.excludeMine !== REFINE_DEFAULTS.excludeMine;

  return (
    <div className="flex flex-wrap items-center gap-2 border-b bg-background px-4 py-2.5">
      <span
        className="flex size-[22px] shrink-0 items-center justify-center rounded-md border bg-muted text-muted-foreground"
        title="Refine in Pyor (client-side filters)"
      >
        <FilterIcon className="size-3.5" />
      </span>
      <Separator orientation="vertical" className="h-7" />

      {/* Comment type */}
      <PickerPopover
        open={pop === 'type'}
        onOpenChange={toggle('type')}
        width={300}
        trigger={
          <span>
            <RefinePill
              icon={MessageSquareIcon}
              label="Type"
              value={refine.type === 'any' ? null : typeCfg.label}
              active={refine.type !== 'any'}
              open={pop === 'type'}
            />
          </span>
        }
      >
        <Command>
          <CommandList>
            <CommandGroup heading="Comment surface">
              {TYPE_ENTRIES.map((e) => (
                <MenuRow
                  key={e.id}
                  active={refine.type === e.id}
                  icon={e.icon}
                  title={e.label}
                  desc={e.desc}
                  onSelect={() => {
                    onRefine({ ...refine, type: e.id });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      {/* Thread state */}
      <PickerPopover
        open={pop === 'thread'}
        onOpenChange={toggle('thread')}
        width={260}
        trigger={
          <span>
            <RefinePill
              icon={CheckCircle2Icon}
              label="Thread"
              value={refine.thread === 'any' ? null : thread.label}
              active={refine.thread !== 'any'}
              open={pop === 'thread'}
            />
          </span>
        }
      >
        <Command>
          <CommandList>
            <CommandGroup heading="Resolution (GraphQL isResolved)">
              {THREAD_OPTIONS.map((o) => (
                <MenuRow
                  key={o.q}
                  active={refine.thread === o.q}
                  icon={o.icon}
                  title={o.label}
                  desc={o.desc}
                  onSelect={() => {
                    onRefine({ ...refine, thread: o.q });
                    setPop(null);
                  }}
                />
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PickerPopover>

      <ToggleSwitch
        label="Unread only"
        active={refine.unreadOnly}
        onClick={() => onRefine({ ...refine, unreadOnly: !refine.unreadOnly })}
      />

      <ToggleSwitch
        label="Hide my comments"
        active={refine.excludeMine}
        onClick={() => onRefine({ ...refine, excludeMine: !refine.excludeMine })}
      />

      <div className="ml-auto flex items-center gap-3 text-[11.5px] text-muted-foreground">
        {dirty && (
          <button
            type="button"
            onClick={() => onRefine(REFINE_DEFAULTS)}
            className="inline-flex items-center gap-1 rounded-md px-1.5 py-1 hover:bg-accent hover:text-foreground"
          >
            <RotateCcwIcon className="size-3" />
            Reset
          </button>
        )}
        <span>
          <span className="tabular-nums text-foreground/80">{fetched}</span> fetched{' '}
          <span className="text-muted-foreground/50">→</span>{' '}
          <b className={cn('font-semibold tabular-nums text-foreground')}>{shown}</b> shown
        </span>
      </div>
    </div>
  );
}
